/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('middleman','Middleman is a transparent compound of middle and man; its commercial sense developed for an intermediary between a maker and buyer.',C('middleman.s1','农产品交易','The village co-op sold its apples directly to the grocer, cutting out the middleman who had previously set the wholesale price.','村合作社把苹果直接卖给杂货商，绕过了此前决定批发价的中间商。','The village co-op sold its apples directly to the grocer / cutting out the middleman / who had previously set the wholesale price.','cut out the middleman 表示省去交易中介；这里指商业居间者。','直接交易使果农与零售商之间不再需要中间商。'),M('The grower sold every apple directly to the customer and described the absent broker as the middleman in the completed sale.','The grower used a broker to arrange the sale and paid the middleman a commission.','没有参与交易的中间人不能被说成该笔交易的中间商。'),[q('Who was cut out of the apple deal?','the broker between grower and grocer','the person who picked the apples','the final grocery customer','middleman 指夹在生产者和买家之间的中介。'),q('Why did the co-op sell directly?','to avoid an intermediary setting the wholesale price','to hire another broker','to turn apples into juice','例句写合作社省去中间商并直接售货。'),q('Which phrase means avoiding an intermediary?','cut out the middleman','cut out the harvest','cut in the retailer','cut out the middleman 是常见表达。',1,'collocation'),q('In the sentence, middleman is a person who?','arranges or stands between the two sides of a deal','buys fruit only for personal use','grows every apple','此处中间商在买卖双方之间促成交易。')]);
P('midget','Midget was first recorded for a tiny biting insect, likely from midge plus diminutive -et; its later label for a person is now widely considered offensive.',C('midget.s1','用词语域','The editor replaced the outdated label with the person’s preferred description, because the old word can demean people with dwarfism.','编辑把过时的称呼换成当事人认可的描述，因为旧词可能贬低患有侏儒症的人。','The editor replaced the outdated label / with the person’s preferred description / because the old word can demean people with dwarfism.','该词指人时有冒犯性，正式写作应使用当事人认可的称呼。','语境讨论的是这个词的贬损风险，不是在给人贴标签。'),M('The report used midget as a respectful neutral term for a person with dwarfism.','The report used the person’s preferred description and noted that midget can be offensive.','把该词称为尊重且中性的常规称呼不符合当代语域。','register'),[q('Why did the editor change the label?','it can demean people with dwarfism','it is the standard medical diagnosis','it means a very tall person','指人时這一旧称可能冒犯或贬损。',1,'register'),q('Which wording follows the editor’s approach?','use the person’s preferred description','use the old label as a joke','invent a diagnosis from the label','例句强调尊重当事人的自我称呼。',1,'word-choice'),q('The word was first recorded for a?','tiny biting insect','mountain range','large farm animal','该词早期记录的含义与小型昆虫有关。'),q('In careful writing about a person, the old label is?','best avoided because it may offend','a neutral technical term','required in every context','讨论的是词语语域，应避免把它当作中性称呼。',1,'register')]);
P('midlatitude','Midlatitude combines mid- (“middle”) with latitude and names the broad zones between the tropics and polar regions.',C('midlatitude.s1','气候研究','The midlatitude storm tracked east across the continent, bringing rain to cities far south of the Arctic Circle.','这场中纬度风暴向东横越大陆，给远在北极圈以南的城市带来降雨。','The midlatitude storm tracked east across the continent / bringing rain to cities / far south of the Arctic Circle.','midlatitude 修饰 storm，指发生在中纬度地区的风暴。','北极圈以南的温带风暴对应中纬度天气系统。'),M('The research team classified a station at 85 degrees north as midlatitude, although it lay inside the Arctic polar region.','The team classified the station near 45 degrees north as midlatitude, between the tropics and polar region.','85°N 位于北极高纬度区，不是中纬度。'),[q('A midlatitude storm occurs in?','the zone between tropical and polar latitudes','the exact North Pole','the equatorial belt only','midlatitude 指热带与极地之间的中纬度带。'),q('Where did the storm move?','east across the continent','south into the ocean floor','upward beyond the atmosphere','例句明确说风暴向东越过大陆。'),q('A station near 45° north is most likely?','in the midlatitudes','at the South Pole','on the equator','45°N 大致属于中纬度。',1,'measurement'),q('Which word is the head noun in midlatitude storm?','storm','latitude','mid','midlatitude 在短语中修饰名词 storm。',1,'grammar')]);
P('midmorning','Midmorning is formed from mid- (“middle”) and morning, referring to the part of the morning after early morning and before noon.',C('midmorning.s1','日程安排','The maintenance crew took its first break in midmorning, after completing the inspection of the west wing.','维修组在上午中段、完成西翼检查后休息了第一次。','The maintenance crew took its first break in midmorning / after completing the inspection / of the west wing.','midmorning 是名词，可作时间状语，常指上午九十点左右。','检查结束后安排在午前中段休息，符合该词时间范围。'),M('The crew scheduled a midmorning break for 3:30 p.m., several hours after noon.','The crew scheduled its midmorning break for about 10:00 a.m.','下午三点半已过正午，不是上午中段。'),[q('When did the crew rest?','during the middle part of the morning','late at night','after the evening meal','midmorning 指早晨和中午之间的时段。'),q('What had the crew finished first?','inspecting the west wing','repairing the east wing next week','eating dinner','例句说休息前完成西翼检查。'),q('Which time best fits midmorning?','about 10 a.m.','about 10 p.m.','just after midnight','上午十点左右符合通常的 midmorning。',1,'measurement'),q('In took a break in midmorning, the word midmorning functions as?','a time noun in an adverbial phrase','a verb describing inspection','an adjective modifying crew','in midmorning 表示休息发生的时间。',1,'grammar')]);
P('midnight','Midnight continues Old English midniht, a compound of mid and night for twelve o’clock at night; the adjective also means occurring then.',[C('midnight.s1','跨日时刻','The train scheduled to leave at midnight on Friday actually departed as Saturday began.','原定星期五午夜出发的列车，实际在星期六刚开始时开出。','The train scheduled to leave at midnight on Friday / actually departed / as Saturday began.','midnight 作名词指一天结束与下一天开始交界的夜间十二点。','句子强调午夜是日期切换点。'),C('midnight.s2','定语用法','A midnight alarm woke the caretaker, who found a delivery van blocking the school gate.','午夜警报惊醒了看门人，他发现一辆送货车堵在校门口。','A midnight alarm woke the caretaker / who found a delivery van / blocking the school gate.','midnight 可作名词前置定语，表示发生在午夜的。','midnight 修饰 alarm，表示午夜响起的警报。')],M('The calendar showed 12:00 noon, but the staff called it midnight.','The calendar showed 12:00 a.m., the point when Friday ended and Saturday began.','12:00 noon 是正午，midnight 是午夜十二点。','confusable'),[q('When did the Friday train leave?','as Saturday began at twelve at night','at noon on Friday','before sunrise on Friday','午夜是星期五结束、星期六开始的时点。',1,'measurement'),q('What woke the caretaker?','an alarm at midnight','a midmorning phone call','a morning train','例句中的警报在午夜响起。',2),q('In midnight alarm, midnight is used as?','a noun modifying another noun','a verb in the past tense','an adverb after the verb','midnight 在 alarm 前作定语。',2,'grammar'),q('Which clock label means midnight?','12:00 a.m.','12:00 p.m.','6:00 p.m.','12:00 a.m. 表示午夜，12:00 p.m. 表示正午。',1,'confusable')]);
P('midocean','Midocean is a modern compound of mid- and ocean for the open sea far from continental margins.',C('midocean.s1','海洋地理','The research vessel released a drifting sensor in midocean, hundreds of kilometres from the nearest coast.','研究船在远离最近海岸数百公里的大洋中部投放了一枚漂流传感器。','The research vessel released a drifting sensor in midocean / hundreds of kilometres / from the nearest coast.','midocean 作名词，指远离大陆边缘的开阔海域。','远离海岸的测点位于大洋中部。'),M('The crew called the sheltered harbour beside the mainland midocean.','The crew called the remote open-water station midocean.','大陆旁的港湾不是远离海岸的大洋中部。'),[q('Where was the sensor released?','in open ocean far from the coast','inside a harbour','on a mountain ridge','midocean 指远离大陆边缘的开阔海域。'),q('How far was the vessel from the nearest coast?','hundreds of kilometres','one metre','inside the harbour wall','例句给出数百公里的距离。'),q('Which location is midocean?','a station in remote open water','a pier inside a coastal town','a riverbank','远海开阔水域符合 midocean。',1,'context'),q('What does mid- contribute to midocean?','the idea of being in the middle','the idea of being beneath','the idea of being noisy','mid- 在这里表示位于海洋中部。',1,'word-formation')]);
P('midriff','Midriff combines mid- with the old word for the belly; it names the body area around the waist, including the diaphragm region.',C('midriff.s1','服装描述','The cropped jacket ended above her waist, leaving a narrow strip of midriff visible when she reached for the shelf.','短夹克下摆在腰部以上，她伸手拿架子时露出一小条腹部。','The cropped jacket ended above her waist / leaving a narrow strip of midriff visible / when she reached for the shelf.','midriff 作名词指腰部附近的躯干中段，不等同于整个胸部。','衣服露出的部位在腰部上方、腹部附近。'),M('The tailor said the jacket exposed the midriff, but it covered the waist and showed only the wearer’s face.','The tailor said the jacket exposed a strip of skin around the waist.','只露出脸并未露出腹部或腰部区域。'),[q('What became visible when she reached up?','a strip of skin around her waist','her ankle below the shoe','the back of her head','midriff 是腰部附近的腹部区域。'),q('Where did the cropped jacket end?','above her waist','below her knees','at her ankles','夹克下摆在腰部以上。'),q('Which clothing description fits?','a top that exposes the midriff','a hat that covers the midriff','shoes around the midriff','露腹短上衣可以露出 midriff。',1,'context'),q('Midriff refers most directly to the body’s?','middle trunk around the waist','lower leg','outer ear','midriff 指躯干腰腹部的中段。')]);
P('midst','Midst is from Middle English middes, an old genitive form related to mid; it appears chiefly in in the midst of for being surrounded by or during.',[C('midst.s1','人群中央','In the midst of the crowd, Priya spotted her brother waving from beside the fountain.','在人群中央，普丽娅看见哥哥在喷泉旁挥手。','In the midst of the crowd / Priya spotted her brother / waving from beside the fountain.','in the midst of + 名词表示处于群体或场所的中间。','兄妹身处人群之中，符合空间义。'),C('midst.s2','事件进行中','The lights failed in the midst of the presentation, so the speaker continued by the emergency exit.','报告进行到一半时灯灭了，演讲者于是借着紧急出口的灯继续讲。','The lights failed / in the midst of the presentation / so the speaker continued / by the emergency exit.','in the midst of + 活动也可表示某事正在进行时。','灯光在报告进行中熄灭，符合时间义。')],M('The lights failed after the presentation had ended, but the report said they failed in the midst of it.','The lights failed while the presentation was still under way.','活动结束后才停电，不能说发生在活动进行之中。','word-choice'),[q('Where was Priya standing?','among the people in the crowd','outside the city','under the fountain','in the midst of the crowd 表示在人群当中。',1,'context'),q('When did the lights fail?','while the presentation was still happening','after the audience had gone home','before the building opened','in the midst of 表示报告尚在进行时。',2,'context'),q('Which phrase correctly means during an event?','in the midst of the meeting','at midst the meeting','in a midst to meeting','固定结构是 in the midst of + 名词。',2,'grammar'),q('In the midst of the crowd, midst means?','the middle or surrounding centre','the edge outside','the conclusion afterward','此处表示人群中央。',1) ]);
P('midterm','Midterm combines mid- and term; as a noun it is an exam halfway through a school term, and as an adjective it describes the middle part of a period.',[C('midterm.s1','学校考试','Lena reviewed the chapters from September before sitting her midterm in the eighth week of the course.','莉娜复习了九月以来的章节，在课程第八周参加期中考试。','Lena reviewed the chapters from September / before sitting her midterm / in the eighth week of the course.','midterm 作名词时常指学期中途的考试。','课程尚未结束，考试设在中段。'),C('midterm.s2','中期评估','The board released a midterm report on the project after six months, with a final evaluation still due in December.','项目进行六个月后，董事会发布了中期报告，最终评估仍定于十二月。','The board released a midterm report on the project / after six months / with a final evaluation still due in December.','midterm 作形容词时修饰 report，表示周期中段的。','六个月时发布、年底才最终评估，因此是中期报告。')],M('A test given on the final day of term was labelled the midterm.','A test given halfway through the term was labelled the midterm.','学期最后一天的考试是期末考试，不是期中考试。'),[q('When did Lena sit her midterm?','in the eighth week, around the course midpoint','on the day after graduation','before the course began','midterm 是课程中段的考试。',1,'measurement'),q('What kind of report did the board release?','an interim report halfway through the project','the final report after completion','a daily attendance list','六个月的报告在项目周期中段发布。',2,'context'),q('In midterm report, midterm is?','an adjective modifying report','a verb describing the board','an adverb modifying released','midterm 在 report 前作定语。',2,'grammar'),q('A midterm exam is taken?','about halfway through a school term','only after the school year ends','before enrolment','期中考试安排在学期中段。',1) ]);
P('midway','Midway combines mid- and way, literally the middle of a route; it is used for a point halfway through a distance or period.',C('midway.s1','旅程进度','We stopped at a roadside cafe midway through the drive from Bristol to York to stretch our legs.','从布里斯托尔开往约克的途中，我们在半路上的路边咖啡馆停下活动腿脚。','We stopped at a roadside cafe / midway through the drive from Bristol to York / to stretch our legs.','midway 可作副词，midway through + 行程/过程表示进行到一半。','停靠点位于整段驾驶行程的中途。'),M('The driver said the cafe was midway through the trip even though it stood at the starting point.','The driver stopped at a cafe around halfway through the trip.','起点不是一段旅程的中途。'),[q('When did the travellers stop?','around halfway through the drive','before leaving Bristol','after reaching York','midway through the drive 表示行程过半时。'),q('Why did they stop?','to stretch their legs','to begin the journey','to cancel the destination','例句说明停留是为了活动腿脚。'),q('Which phrase is natural?','midway through the journey','midway at the journey','midway into of the journey','midway through 表示进行到过程的中间。',1,'collocation'),q('Midway most nearly means?','halfway along a route or process','at the very beginning','far beyond the end','该词指距离或过程中的中点。')]);
P('midweek','Midweek is a compound of mid- and week for the middle part of a week, commonly around Wednesday.',C('midweek.s1','预约时间','The clinic has more appointment slots midweek than on Monday or Friday, so Omar booked Wednesday morning.','诊所周中比周一或周五有更多预约时段，因此奥马尔订了周三上午。','The clinic has more appointment slots midweek / than on Monday or Friday / so Omar booked Wednesday morning.','midweek 可作名词或副词，指一周中段，通常约在周三。','周三预约符合一周中段的时间。'),M('The office called Sunday midweek in its Monday-to-Friday schedule.','The office treated Wednesday as midweek in its Monday-to-Friday schedule.','在周一至周五的工作周里，周日不是周中。'),[q('Which day did Omar choose?','Wednesday morning','Saturday night','Monday at dawn','周三通常处于一周中段。'),q('Why was Wednesday useful?','the clinic had more open slots midweek','the clinic was closed all week','the journey ended on Friday','例句明确说明周中有更多可预约时段。'),q('In booked Wednesday midweek, midweek works as?','a time adverb','a countable verb','a plural adjective','midweek 在句中说明预约时间。',1,'grammar'),q('For a Monday-to-Friday workweek, midweek is closest to?','Wednesday','Monday','Friday night','在常见工作周中，周三最接近中段。')]);
P('midwestern','Midwestern is Midwestern (Middle West) plus adjective-forming -ern, describing the north-central United States or its people and culture.',C('midwestern.s1','地域文化','Her Midwestern relatives drove from Iowa for the reunion and brought a tray of homemade corn bread.','她来自艾奥瓦州的美国中西部亲戚开车来参加团聚，还带了一盘自制玉米面包。','Her Midwestern relatives drove from Iowa / for the reunion / and brought a tray of homemade corn bread.','Midwestern 作地域形容词，首字母通常大写，修饰 relatives。','艾奥瓦州位于美国中西部，来访亲属符合地域义。'),M('A family from coastal Maine was described as Midwestern solely because it lived beside the Atlantic.','A family from Iowa was described as Midwestern because Iowa is in the US Middle West.','缅因州在美国东北部大西洋沿岸，不是中西部。'),[q('Where did the relatives come from?','Iowa in the north-central United States','coastal Maine','southern Florida','艾奥瓦州位于美国中西部。'),q('What did they bring?','homemade corn bread','a seafood net','a train ticket','亲戚带来一盘自制玉米面包。'),q('Which place is Midwestern?','Illinois','California’s Pacific coast','the Florida Keys','伊利诺伊州属于美国中西部。',1,'context'),q('Why is Midwestern capitalized in the example?','it is a regional adjective derived from a proper US region','it begins every adjective with a capital','it is a person’s first name','地域名称派生词通常保留大写。',1,'capitalization')]);
P('midwife','Midwife comes from Middle English mid (“with”) plus wif (“woman”), literally a woman with the mother during birth; figuratively, it can help bring a project into being.',[C('midwife.s1','产科护理','The midwife checked the mother’s progress and explained when to call the hospital during early labour.','助产士检查产妇的进展，并说明早期分娩时何时应联系医院。','The midwife checked the mother’s progress / and explained / when to call the hospital / during early labour.','midwife 作名词指受训的助产专业人员。','检查产程并提供分娩指导是助产士职责。'),C('midwife.s2','比喻促成','A small grant acted as midwife to the community garden, helping neighbours turn an empty lot into a shared space.','一笔小额资助促成了社区花园，帮助邻居把空地变成共享空间。','A small grant acted as midwife to the community garden / helping neighbours turn an empty lot / into a shared space.','比喻用法指帮助新计划或新事物诞生的人或事物。','资助帮助花园项目从计划变为现实。')],M('The novel called the grant a midwife because it prevented the community project from ever starting.','The novel called the grant a midwife because it helped the community project come into being.','阻止项目启动与促成项目诞生意思相反。'),[q('What did the midwife check?','the mother’s progress in labour','the community garden budget','the hospital roof','产科义项关注母亲的产程进展。',1,'context'),q('How did the grant act as a midwife?','it helped the garden project come into being','it closed the garden permanently','it treated a newborn infant','比喻义是促成计划或事物诞生。',2),q('The word literally contains a historical mid meaning?','with','halfway','against','midwife 中的 mid 源于旧词“与……同在”。',1,'word-formation'),q('Which sentence uses midwife figuratively?','The grant midwifed a new arts centre.','The midwife monitored a birth.','The nurse measured the infant.','资助促成艺术中心属于比喻用法。',2,'context')]);
P('might','Might is the past form of may, now widely used for possibility or a polite suggestion; the separate noun might means strength or power.',[C('might.s1','不确定推测','The sky is clearing, so the ferry might run this afternoon, but the operator has not confirmed it.','天空正在放晴，因此渡船下午可能会运行，但运营方尚未确认。','The sky is clearing / so the ferry might run this afternoon / but the operator has not confirmed it.','might + 动词原形表示不确定的可能性。','运营方尚未确认，句子表达的是可能而非确定。'),C('might.s2','委婉建议','You might ask the librarian to reserve the archive box before travelling across town.','你可以请图书管理员预留档案盒，然后再穿城过去。','You might ask the librarian / to reserve the archive box / before travelling across town.','you might + 动词原形可作委婉建议，而非过去时。','此处是温和建议先联系图书馆。'),C('might.s3','过去推测','The mechanic might have left the spare key in the desk, although nobody has checked the drawer yet.','修理工可能把备用钥匙留在桌子里了，不过还没人检查抽屉。','The mechanic might have left the spare key / in the desk / although nobody has checked the drawer yet.','might have + 过去分词表示对过去事件的不确定推测。','have left 指向过去，might 保留不确定性。'),C('might.s4','力量','The old bridge withstood the river’s full might during the spring flood.','春季洪水期间，老桥经受住了河流的全部威力。','The old bridge withstood the river’s full might / during the spring flood.','名词 might 表示力量或威力，常见搭配 full might。','洪水的冲击力是句中的力量义。')],M('The operator had already confirmed the ferry was cancelled, but the notice said it might run for certain.','The operator had not confirmed service, so the notice said the ferry might run.','might 表示可能，并不能与“已确定”同义。','meaning'),[q('Is the ferry definitely running?','no; it is only possible','yes; the operator confirmed it','no; the ferry sank last year','might 表示不确定可能性。',1,'meaning'),q('What does You might ask the librarian do?','make a polite suggestion','report a completed past action','describe a river flood','you might ask 在此委婉建议采取行动。',2,'context'),q('Might have left points to a guess about?','a past action','a guaranteed future action','a person’s physical strength','might have + 过去分词表示对过去的推测。',3,'grammar'),q('The river’s might means its?','great force','uncertain schedule','library archive','名词 might 是力量或威力。',4,'meaning')]);
P('mighty','Mighty comes from Old English mihtig, “strong, powerful,” formed with the adjective ending -ig; it also appears as an emphatic adverb and a noun for a powerful person.',[C('mighty.s1','自然力量','A mighty gust knocked the sign from its post and sent it sliding across the wet pavement.','一阵强劲的狂风把标牌从立柱上吹落，并使它滑过湿漉漉的人行道。','A mighty gust knocked the sign from its post / and sent it sliding / across the wet pavement.','mighty 作形容词修饰 gust，强调力量或强度很大。','强风把标牌吹落，表现出很大的力量。'),C('mighty.s2','强权人物','The novel follows a mighty who loses influence after ignoring the needs of ordinary citizens.','这部小说讲述一位有权势者因忽视普通民众需求而失去影响力。','The novel follows a mighty / who loses influence / after ignoring the needs of ordinary citizens.','mighty 可名词化指强大或有权势的人，常见于文学语境。','人物失去影响力说明其原先拥有权势。'),C('mighty.s3','程度副词','The hikers were mighty glad to find a warm shelter when the hail began.','冰雹开始落下时，徒步者们找到温暖避难处，心里非常高兴。','The hikers were mighty glad / to find a warm shelter / when the hail began.','口语或非正式用法中，mighty 可作程度副词，意为非常。','mighty 修饰 glad，表示程度很高。')],M('A mighty gust was described as powerless even though it tore the sign from its post.','A mighty gust tore the sign from its post with great force.','把强风说成没有力量与 mighty 的语义相冲突。'),[q('What did the mighty gust do?','it tore a sign from its post','it warmed the hikers','it made the storm disappear','mighty 强调风力强劲。',1),q('In the novel, a mighty is?','a person with great power','a small weather instrument','a type of shelter','名词化的 mighty 指有权势的人。',2),q('In mighty glad, mighty means?','very','slightly','never','口语中 mighty 可作 very 的强调用法。',3,'confusable'),q('Which part of speech is mighty in a mighty gust?','adjective','noun only','preposition','mighty 修饰名词 gust，是形容词。',1,'grammar')]);
P('migraine','Migraine came through French from Greek hēmikrania, literally “half the skull,” describing a severe recurring headache often affecting one side.',C('migraine.s1','症状描述','Nora went to a quiet room when the migraine began, because light and noise made the one-sided pain worse.','偏头痛发作时，诺拉去了安静的房间，因为光线和噪声会加重一侧头部的疼痛。','Nora went to a quiet room when the migraine began / because light and noise / made the one-sided pain worse.','migraine 是可数名词，指常伴有感官不适的严重头痛；例句未将其当普通头疼。','一侧疼痛并对光和声音敏感，符合偏头痛情境。'),M('Nora had a migraine, but the only symptom was a painless itch on her ankle.','Nora had a migraine with severe one-sided head pain worsened by light.','脚踝无痛瘙痒并非例句中描述的偏头痛症状。'),[q('What worsened Nora’s pain?','light and noise','warm soup and water','a loose shoelace','例句指出光线与噪声会加重疼痛。'),q('Where was the pain described?','on one side of her head','in both ankles','in her fingertips only','migraine 的典型表述常涉及一侧头痛。'),q('Which response fits the episode?','move to a quiet, dim room','turn up bright lights','start a noisy concert','减少光线和噪声符合她的症状。',1,'context'),q('The Greek source hēmikrania literally refers to?','half the skull','a full stomach','a weak heartbeat','词源字面上指头颅的一半。')]);
P('migrant','Migrant comes from Latin migrans, “moving,” from migrare; it can name a person who moves for residence or work, or a seasonally travelling bird.',[C('migrant.s1','劳工流动','The migrant worker followed the harvest north and rented a room near each farm for a few weeks.','这名流动工人跟着收获季向北迁移，在每个农场附近租住几周。','The migrant worker followed the harvest north / and rented a room / near each farm for a few weeks.','migrant 作名词指迁往别处居住或就业的人，worker 限定其身份。','随季节工作而辗转各地的工人符合迁移人口义。'),C('migrant.s2','鸟类迁徙','The reserve counted thousands of migrant geese arriving from the north before winter.','保护区统计了数千只冬季前从北方飞来的候鸟。','The reserve counted thousands of migrant geese / arriving from the north / before winter.','migrant 可修饰鸟类，指随季节迁徙的动物。','冬前从北方迁来的雁属于候鸟。')],M('The reserve called geese migrant birds even though they stayed in one small pond all year.','The reserve called the geese migrant birds because they travelled south each winter.','全年留在同一地点的鸟不符合季节迁徙的描述。'),[q('Why did the worker move north?','to follow seasonal harvest work','to escape a winter storm at sea','to attend a one-day lecture','随收获季移动体现就业迁移。',1,'context'),q('What does migrant describe before geese?','birds that travel seasonally','birds that never leave one pond','geese raised only in a farm building','migrant 修饰 geese，指随季节迁徙。',2),q('Which person is a migrant worker?','someone who moves between regions for jobs','a farmer who never changes workplace','a tourist on a single-day visit','为工作迁居或流动的人可称 migrant worker。',1),q('Which word is closest to migrant in the worker sense?','移居者','landlord','visitor who stays one hour','migrant 指移往别处生活或工作的个体。',1,'meaning')]);
P('migrate','Migrate comes from Latin migrare, “to move from one place to another”; modern uses include seasonal animal travel, human relocation, and data transfer.',[C('migrate.s1','候鸟迁徙','The cranes migrate south each autumn and return to the same wetlands when spring arrives.','每年秋天，鹤群向南迁徙，春天到来时又返回同一片湿地。','The cranes migrate south each autumn / and return to the same wetlands / when spring arrives.','migrate 不及物用法可指动物按季节迁徙，常与方向副词连用。','秋南迁、春返回是规律性季节迁徙。'),C('migrate.s2','人口移居','After the factory closed, several families migrated to the coast to find steadier work.','工厂关闭后，几户人家迁往海岸寻找更稳定的工作。','After the factory closed / several families migrated to the coast / to find steadier work.','migrate 可表示人迁往另一个地区居住或就业。','家庭因工作迁居，符合人口迁移义。'),C('migrate.s3','系统迁移','The library will migrate its catalogue to a new database overnight, keeping the old records available during the change.','图书馆将在夜间把目录迁移到新数据库，并在转换期间保留旧记录供人查询。','The library will migrate its catalogue to a new database overnight / keeping the old records available / during the change.','技术语境中 migrate 是及物动词，可接数据或系统作宾语。','catalogue 从旧数据库转移到新数据库，属于技术迁移。')],M('The cranes migrated south each autumn and then stayed in the north through every winter.','The cranes migrated south each autumn and returned north in spring.','秋天向南迁徙后仍留在北方过冬，方向与季节规律矛盾。'),[q('What do the cranes do each autumn?','travel south with the season','move a catalogue to a database','settle permanently in the north','例句描述的是鸟类季节迁徙。',1,'context'),q('Why did the families move to the coast?','to find steadier work','to return the library catalogue','to avoid spring wetlands','家庭为寻找工作而迁居。',2,'context'),q('What will the library migrate?','its catalogue to a new database','the cranes to a wetland','the families to the coast','技术义中 migrate 的宾语是目录数据。',3,'grammar'),q('Which verb pattern appears in the technology sense?','migrate data to a new system','migrate to data a system','migrate data by a new system only','及物 migrate 常用 migrate data to a system。',3,'collocation')]);
P('migration','Migration comes from Latin migratio, from migrare (“move”); it names human relocation, seasonal animal travel, and transfer between computer systems.',[C('migration.s1','人口变化','The town’s migration report showed that more families moved in for work than moved away during the year.','该镇的人口迁移报告显示，这一年因工作迁入的家庭多于迁出的家庭。','The town’s migration report showed / that more families moved in for work / than moved away / during the year.','migration 可指人口从一地迁往另一地的现象。','报告统计的是家庭迁入和迁出。'),C('migration.s2','动物季节迁徙','Satellite tags revealed the migration of sea turtles between feeding grounds and nesting beaches.','卫星标签揭示了海龟在觅食地与筑巢海滩之间的迁徙路线。','Satellite tags revealed the migration of sea turtles / between feeding grounds / and nesting beaches.','migration 可指动物为繁殖或季节变化而规律移动。','觅食地与筑巢地之间往返属于动物迁徙。'),C('migration.s3','数据迁移','The bank scheduled its database migration for Sunday night, when fewer customers would need online access.','银行把数据库迁移安排在周日夜间，因为那时需要在线访问的客户较少。','The bank scheduled its database migration for Sunday night / when fewer customers / would need online access.','IT 语境中 migration 指将数据或系统转移到新位置或形式。','数据库更换安排在低使用时段进行。')],M('The database migration copied no data and left the bank’s records on the old system permanently.','The database migration transferred the bank’s records to the new system.','数据完全没有转移就不构成数据库迁移。'),[q('What did the town report measure?','families moving into and out of the town','turtles nesting on the beach','bank customers logging in','人口迁移报告统计家庭迁入迁出。',1,'context'),q('Which animals were tracked between feeding and nesting sites?','sea turtles','migrant geese only','farm cattle','例句说卫星标签揭示海龟的迁徙。',2),q('Why was the bank’s migration scheduled at night?','fewer customers would need online access','turtles migrate only at night','the town report was due then','低使用时段减少数据库切换对客户的影响。',3,'context'),q('Database migration refers to?','moving data or systems to a new platform','moving a family to the coast','a turtle’s nesting season','migration 在 IT 中指数据或系统迁移。',3) ]);
P('migratory','Migratory derives from Latin migratorius, based on migrator (“one who moves”); it describes seasonal animal movement and people who move frequently.',[C('migratory.s1','鸟类习性','The migratory swallows gather over the marsh before flying south as the weather turns colder.','天气转冷时，迁徙的燕子聚集在沼泽上空，准备向南飞。','The migratory swallows gather over the marsh / before flying south / as the weather turns colder.','migratory 作形容词修饰 swallows，说明它们随季节迁徙。','燕子因天气转冷而准备南飞，符合迁徙性。'),C('migratory.s2','流动就业','The agency provided temporary housing for migratory workers who followed fruit-picking jobs between regions.','该机构为随采果工作在不同地区流动的工人提供临时住房。','The agency provided temporary housing / for migratory workers / who followed fruit-picking jobs between regions.','migratory 也可修饰劳工，指因工作而经常迁移的。','工人随农活跨地区流动，符合流动劳工义。')],M('The migratory swallows were described as seasonal travellers even though they remained in the same marsh all year.','The migratory swallows flew south as winter approached and returned in spring.','全年留在同一片沼泽不符合季节迁徙。'),[q('Why were the swallows gathering?','they were preparing for a seasonal flight south','they had completed a database transfer','they were nesting in a city office','天气转冷触发燕子向南迁徙。',1,'context'),q('What makes the workers migratory?','they follow jobs from one region to another','they work in one fixed office all year','they manage bird habitats','工人随地区变化的采果工作迁移。',2),q('Which phrase contains migratory in its animal sense?','migratory cranes flying south','migratory data saved overnight','migratory furniture in a shop','动物按季节飞行体现 migratory。',1,'context'),q('Migratory is best described as?','an adjective for regular movement between places','a noun for a work contract','a verb meaning to calculate','migratory 在两句中都作形容词修饰名词。')]);

(function(){
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('mike','Mike is an informal clipping of microphone, used especially for a microphone at a performance or recording session.',C('mike.s1','录音设备','The sound engineer lowered the mike before the singer tested the first note.','歌手试唱第一个音符前，音响师把麦克风放低了。','The sound engineer lowered the mike / before the singer tested / the first note.','mike 是 microphone 的口语缩略形式，指麦克风。','音响师调整的是拾音设备的位置。'),M('The singer spoke into a mike, but the engineer insisted it was a camera for taking photographs.','The singer spoke into the mike while the engineer adjusted its height.','用于扩音或录音的设备是麦克风，不是相机。'),[q('What did the engineer lower?','the microphone','the camera lens','the music stand','mike 是 microphone 的非正式简称。'),q('Who tested the first note?','the singer','the sound engineer','the audience conductor','例句说歌手要试唱音符。'),q('Which is the full form of mike here?','microphone','microscope','microchip','mike 在此缩略自 microphone。',1,'word-formation'),q('Where might a singer use a mike?','on stage or in a recording studio','in a kitchen oven','inside a car tyre','麦克风用于扩音或录音。',1,'context')]);
P('mild','Mild comes from Old English milde (“gentle, gracious”); it describes moderate weather, illness, taste, or temperament.',[C('mild.s1','天气状况','The coast had a mild winter, with few frosts and daytime temperatures often above ten degrees.','沿海地区冬季温和，霜冻很少，白天气温常在十度以上。','The coast had a mild winter / with few frosts / and daytime temperatures often above ten degrees.','mild 修饰 winter，指天气不冷不严酷。','少霜且白天气温较高说明冬季温和。'),C('mild.s2','病情程度','The doctor described the rash as mild and asked Sam to return if it spread or became painful.','医生说皮疹较轻，并让山姆在皮疹扩散或疼痛时复诊。','The doctor described the rash as mild / and asked Sam to return / if it spread or became painful.','mild 可描述症状不严重，常与 illness、symptom 或 case 连用。','医生仅要求观察变化，说明病情不重。'),C('mild.s3','口味强弱','Rosa chose a mild cheese for the children because its flavour was creamy rather than sharp.','罗莎给孩子们选了味道温和的奶酪，因为它口感柔和而不辛辣浓烈。','Rosa chose a mild cheese for the children / because its flavour was creamy / rather than sharp.','mild 可形容味道淡而不刺激。','creamy rather than sharp 对比了温和与强烈口味。'),C('mild.s4','性情温和','Even when the debate grew heated, Professor Hall remained mild and listened without raising her voice.','即使辩论变得激烈，霍尔教授仍然温和，没有提高嗓门而是继续倾听。','Even when the debate grew heated / Professor Hall remained mild / and listened without raising her voice.','mild 可形容性格或态度和善、不暴躁。','不提高嗓门并耐心倾听体现温和性情。')],M('The doctor called Sam’s severe, painful infection mild and sent him home without checking it.','The doctor called Sam’s slight, painless rash mild and asked him to monitor it.','严重而疼痛的感染不能准确描述为轻微病症。'),[q('What was the coast’s winter like?','not very cold or severe','full of deep frost every day','extremely hot','few frosts and warm daytime readings indicate mild weather。',1,'context'),q('A mild rash is?','not severe','always life-threatening','a flavour of cheese','mild 在病情语境表示轻微、不严重。',2),q('Which flavour would be mild?','creamy and not sharp','intensely hot and biting','bitter enough to burn','mild 可描述不浓烈、不刺激的味道。',3),q('Professor Hall remained mild means she was?','gentle and calm','angry and threatening','physically ill','人物性情义表示温和和善。',4)]);
P('mildew','Mildew is recorded in Middle English as mildeu, from Old English meledeaw (“honeydew”); the name shifted from sweet plant secretion to a fungus growing in damp conditions.',C('mildew.s1','潮湿霉菌','A patch of mildew appeared behind the wardrobe where the outside wall stayed cold and damp.','衣柜后面出现一片霉菌，因为外墙一直又冷又潮。','A patch of mildew appeared behind the wardrobe / where the outside wall / stayed cold and damp.','mildew 作不可数名词，也可说 a patch of mildew，指潮湿处生长的霉菌。','冷湿墙面为霉菌生长提供了条件。'),M('The inspector identified mildew on the dry, sunlit wall where no fungus or dampness was present.','The inspector identified mildew on the damp wall behind the wardrobe.','没有潮湿且看不到真菌的干燥墙面不符合霉菌语境。'),[q('Why did mildew grow behind the wardrobe?','the wall stayed cold and damp','the wall was dry and sunny','the room had no outside wall','潮湿环境促使霉菌生长。'),q('Where was the patch found?','behind the wardrobe','inside a sealed food tin','on the sunny roof','霉斑出现在衣柜后的墙面。'),q('Which condition encourages mildew?','poor ventilation and dampness','constant dry heat','a clean, dry surface','潮湿环境利于 mildew 生长。',1,'context'),q('The historical word meledeaw referred to?','honeydew before the meaning shifted','a type of wardrobe','a dry stone wall','mildew 的早期形式与“蜜露”一词有关。')]);
P('mildly','Mildly is mild plus -ly and means to a small degree, or in a gentle and not severe manner.',C('mildly.s1','程度表达','The committee was mildly surprised by the early delivery, since it had expected the equipment the following week.','委员会对提前送达略感意外，因为他们原以为设备下周才到。','The committee was mildly surprised / by the early delivery / since it had expected the equipment / the following week.','mildly 修饰 surprised，表示程度较轻。','委员会只是略感意外，并非震惊。'),M('The committee was mildly surprised and completely speechless with shock for the rest of the day.','The committee was mildly surprised but quickly accepted the early delivery.','mildly 表示程度有限，与持续震惊到说不出话不协调。','word-choice'),[q('How surprised was the committee?','only a little','so shocked they could not speak','not surprised at all by anything','mildly 表示轻微程度。'),q('Why were they surprised?','the equipment arrived early','the delivery was delayed a month','the meeting moved outdoors','送货时间早于预期。'),q('In the sentence, mildly modifies?','the adjective surprised','the noun equipment','the verb expected','副词 mildly 修饰形容词 surprised。',1,'grammar'),q('Which phrase is closest in meaning?','slightly surprised','utterly astonished','angrily surprised','slightly 与 mildly 表示轻微程度。',1,'confusable')]);
P('mile','Mile comes from Old English mil, from Latin milia passuum (“a thousand paces”); the standard international mile is 1,609.344 metres.',[C('mile.s1','长度单位','The trail marker said the lake was three miles ahead, so the walkers filled their bottles before continuing.','路标写着湖还在三英里外，因此徒步者继续前先装满水瓶。','The trail marker said / the lake was three miles ahead / so the walkers filled their bottles / before continuing.','mile 是长度单位，国际英里等于 1,609.344 米。','路标用英里标示剩余距离。'),C('mile.s2','强调遥远','The two proposals are miles apart: one funds local clinics, while the other would close them.','这两项提案大相径庭：一项资助地方诊所，另一项却要关闭诊所。','The two proposals are miles apart / one funds local clinics / while the other would close them.','miles apart 可引申为观点、结果或差异相距甚远。','资助诊所与关闭诊所代表鲜明相反的立场。')],M('The trail guide stated that one mile was exactly one metre.','The trail guide stated that one mile was about 1,609 metres.','英里与米不是一比一换算。','measurement'),[q('How far ahead was the lake?','three miles','three metres','three hours','路标给出三英里的距离。',1,'measurement'),q('What does miles apart mean about the proposals?','they differ greatly','they are physically beside each other','they cost exactly the same','该短语可比喻意见或方案差异很大。',2,'context'),q('One international mile equals about?','1,609 metres','100 metres','1,609 kilometres','英里约为1,609米。',1,'measurement'),q('Which phrase can describe a major disagreement?','Their views are miles apart.','Their views are one metre long.','Their views are three hours ahead.','miles apart 可表示观点相差甚远。',2,'collocation')]);
P('mileage','Mileage combines mile with -age and means distance measured in miles or, especially for vehicles, distance travelled per unit of fuel.',C('mileage.s1','汽车能耗','The hybrid averaged high mileage on the motorway, travelling more than fifty miles on each gallon of fuel.','这辆混合动力车在高速公路上的燃油里程很高，每加仑燃油行驶超过五十英里。','The hybrid averaged high mileage on the motorway / travelling more than fifty miles / on each gallon of fuel.','mileage 可表示每单位燃料能行驶的距离；high mileage 也可指累计里程高，需看语境。','每加仑行驶英里数描述燃油效率。'),M('The car had poor mileage, travelling 600 miles on one gallon of fuel.','The car had high mileage, travelling 600 miles on one gallon of fuel.','每加仑行驶距离极高表示燃油效率好，不是 poor mileage。','meaning'),[q('What does the hybrid’s mileage describe here?','distance travelled per gallon of fuel','the car’s number of doors','the distance from the motorway to the garage','每加仑行驶英里数是燃油效率指标。'),q('Was its fuel efficiency high or low?','high','low','not measured in the example','例句说每加仑超过五十英里，称 mileage 高。'),q('Which vehicle has better fuel mileage?','one travelling farther on each litre','one using more fuel for the same trip','one with a louder engine','单位燃料行驶更远表示里程效率更高。',1,'context'),q('Mileage derives from which distance unit?','mile','metre','minute','构词基础是 mile 加 -age。',1,'word-formation')]);
P('milestone','Milestone began as a stone beside a road marking the miles to a destination; it later became a metaphor for a significant stage of progress.',[C('milestone.s1','道路标记','The surveyor photographed the old milestone beside the Roman road, whose carved number showed the distance to the city.','测量员拍下罗马道路旁的旧里程碑，石上刻的数字标示着到城市的距离。','The surveyor photographed the old milestone / beside the Roman road / whose carved number showed / the distance to the city.','milestone 的本义是标示距离的路边石柱。','刻有距离数字的石标体现本义。'),C('milestone.s2','发展节点','Publishing its first accessible edition was a milestone for the journal, which had excluded screen-reader users for years.','出版首个无障碍版本是该期刊的重要进展，此前它多年来一直未能服务屏幕阅读器用户。','Publishing its first accessible edition / was a milestone for the journal / which had excluded screen-reader users / for years.','milestone 比喻发展中的重要阶段或值得纪念的成就。','首次提供无障碍版本标志着期刊的重要改变。')],M('The team called its first successful field trial a setback and said it marked no progress.','The team called its first successful field trial a milestone in the project.','首次成功试验是重大进展，不是挫折。'),[q('What did the old road milestone show?','the distance to the city','the road’s speed limit','the date the surveyor was born','路边里程碑以刻字标示到目的地的距离。',1),q('Why was the accessible edition a milestone?','it marked an important change for the journal','it measured road miles to a city','it ended all publishing','无障碍版本是期刊发展的重要节点。',2),q('Which event could be called a milestone?','a company opens its first overseas office','a routine email is sent','a printer runs out of paper','首次开设海外办公室可能是重要发展阶段。',2,'context'),q('The literal milestone was made to mark?','distance along a road','a time of day','a person’s job title','milestones originally marked road distance.',1,'meaning')]);
P('milieu','Milieu entered English from French milieu, literally “middle place,” from mi (“middle”) plus lieu (“place”); it means a person’s social or cultural surroundings.',C('milieu.s1','社会环境','Growing up in a bilingual fishing town shaped her artistic milieu, where sea stories and two languages mixed naturally.','在双语渔镇长大塑造了她的艺术环境，海洋故事与两种语言在那里自然交融。','Growing up in a bilingual fishing town / shaped her artistic milieu / where sea stories and two languages / mixed naturally.','milieu 作名词，指影响一个人的社会、文化或思想环境。','渔镇的语言与故事构成她创作所处的环境。'),M('The critic described the author’s milieu as her social surroundings, then defined it as a single isolated dictionary page.','The critic described the author’s milieu as the people, language, and culture surrounding her.','单独一页纸不是人的社会文化环境。'),[q('What shaped her artistic milieu?','a bilingual fishing town and its culture','a single dictionary page','a mountain she never visited','地方语言和文化形成了她的环境。'),q('Milieu most nearly means?','social and cultural surroundings','a measured distance','a kind of storm','该词指社会或文化环境。'),q('Which could be someone’s intellectual milieu?','the ideas and people they encounter daily','the exact room temperature only','a list of road mile markers','日常接触的思想和人构成思想环境。',1,'context'),q('What does French milieu literally mean?','middle place','new language','long road','法语构词为 mi “中间”加 lieu “地方”。',1,'word-formation')]);
P('militant','Militant comes from Latin militantem, “serving as a soldier”; it describes forceful activism or a person who pursues a cause with strong action.',[C('militant.s1','行动风格','The militant campaigners blocked the company gate and demanded that the unsafe equipment be removed immediately.','激进的活动人士堵住公司大门，要求立即撤走不安全设备。','The militant campaigners blocked the company gate / and demanded / that the unsafe equipment / be removed immediately.','militant 作形容词，描述为目标采取强硬行动的方式；不必然等于暴力。','堵门并强硬要求整改体现激进行动。'),C('militant.s2','积极分子','A militant in the tenants’ union organised a rent strike after the landlord ignored repeated repair requests.','租户工会的一名激进成员在房东多次无视维修请求后，组织了拒付租金行动。','A militant in the tenants’ union organised a rent strike / after the landlord ignored / repeated repair requests.','militant 作名词指积极采取强硬行动支持某事业的人。','组织罢租行动的成员符合名词义。')],M('The militant campaigners accepted every delay quietly and took no action for their cause.','The militant campaigners organised a forceful protest to press their cause.','完全不行动且接受拖延不能体现 militant 的积极强硬态度。','meaning'),[q('What did the militant campaigners demand?','removal of unsafe equipment','a rent increase','the company gate be widened','他们采取强硬行动要求排除安全隐患。',1),q('What did the tenants’ union militant organise?','a rent strike','a company picnic','a road survey','名词 militant 是组织行动的工会积极成员。',2),q('Does militant always mean violent?','no; it can mean forcefully active for a cause','yes; it only means armed and violent','no; it means completely passive','militant 可指强硬积极，不必然指暴力。',1,'meaning'),q('Which phrase fits the adjective use?','militant campaigners','militantly campaigners','campaign militantly people','形容词 militant 修饰名词 campaigners。',1,'grammar')]);
P('militarily','Militarily is military plus -ly and means with regard to armed forces, military strategy, or the use of force.',C('militarily.s1','战略分析','The island was militarily important because its runway could support aircraft during a regional emergency.','这座岛在军事上很重要，因为发生地区紧急情况时，其跑道可供飞机使用。','The island was militarily important / because its runway could support aircraft / during a regional emergency.','militarily 是副词，修饰 important，说明重要性体现在哪一方面。','跑道的战略用途说明其军事价值。'),M('The report said the island was militarily important because its bakery sold excellent bread.','The report said the island was militarily important because its runway could support military aircraft.','面包品质不能说明军事重要性。'),[q('Why was the island militarily important?','its runway could support aircraft','its bakery sold bread','its beach was crowded','军用飞机可使用跑道，形成战略价值。'),q('Militarily answers which question here?','important in what respect?','how many islands?','when did the runway open?','副词说明岛屿重要性的军事方面。',1,'grammar'),q('Which concern is assessed militarily?','whether a pass can be defended by troops','whether a song is pleasant','whether a meal is spicy','防守能力属于军事评估。',1,'context'),q('Militarily is formed from military plus?','-ly','-ness','-ment','副词后缀 -ly 加在 military 后。',1,'word-formation')]);
P('militaristic','Militaristic combines military with -istic and describes an outlook that glorifies armed strength or favours military solutions.',C('militaristic.s1','政治观念','The historian called the regime militaristic because its leaders praised conquest and gave soldiers control over civilian schools.','历史学家称该政权穷兵黩武，因为领导人赞扬征服，还让军人控制民用学校。','The historian called the regime militaristic / because its leaders praised conquest / and gave soldiers control / over civilian schools.','militaristic 带批评意味，指崇尚军事力量并偏好武力解决问题。','赞扬征服并让军方控制民用教育，显示崇军观念。'),M('The reviewer called the pacifist group militaristic even though it rejected armed force and disbanded its weapons unit.','The reviewer called the regime militaristic because it glorified conquest and armed control.','拒绝武力、解散武装组织与崇尚军事力量相反。','meaning'),[q('Why did the historian call the regime militaristic?','it glorified conquest and expanded military control','it abolished the army','it funded only civilian libraries','政权赞扬征服并扩大军方影响。'),q('Militaristic has what tone here?','critical of an outlook favouring force','neutral praise of peaceful teaching','a medical diagnosis','此词通常批评崇军或好战观念。',1,'register'),q('Which policy sounds militaristic?','solving disputes by threats of armed force','settling disputes through mediation','closing weapons factories','偏好武力解决争端体现军国主义倾向。',1,'context'),q('Militaristic is built from military and?','-istic','-able','-less','该形容词使用后缀 -istic。',1,'word-formation')]);
P('military','Military comes from Latin militaris, “of soldiers or war,” related to miles (“soldier”); it is an adjective and also a collective noun for armed forces.',[C('military.s1','国防装备','The military aircraft landed at the base after completing a training flight over the coast.','这架军用飞机在海岸上空完成训练飞行后降落在基地。','The military aircraft landed at the base / after completing a training flight / over the coast.','military 作形容词修饰 aircraft，表示与军队或国防有关。','训练飞行和基地表明飞机的军事用途。'),C('military.s2','武装部队','The military announced that rescue teams had reached the flooded valley and were carrying medical supplies.','军方宣布救援队已抵达洪水淹没的山谷，正在运送医疗物资。','The military announced / that rescue teams had reached the flooded valley / and were carrying medical supplies.','the military 作集合名词，指一个国家的武装部队。','由军方发布救援行动信息，符合集合义。')],M('The military aircraft was a civilian crop-spraying plane with no armed-forces role.','The military aircraft carried personnel on a training mission for the armed forces.','没有军事用途的民用飞机不应称为 military aircraft。'),[q('What kind of flight had the aircraft completed?','a training flight for the armed forces','a commercial passenger trip','a crop-spraying trip','military aircraft 指军用飞机。',1,'context'),q('Who announced the rescue teams’ arrival?','the armed forces as a group','the aircraft runway','one private tourist','the military 作集合名词指军方。',2),q('In military aircraft, military is?','an adjective before a noun','a plural noun after a verb','an adverb','military 修饰名词 aircraft。',1,'grammar'),q('The military can mean?','a country’s armed forces collectively','one individual soldier only','a civilian medical school','the military 可集合指武装部队。',2) ]);
P('militia','Militia entered English through Italian militia from Latin militia, “military service”; it names an armed body of citizens outside a regular professional army.',C('militia.s1','武装组织','The local militia guarded the mountain pass until the national army arrived to secure the border.','当地民兵组织守卫山口，直到国民军抵达并接管边境防务。','The local militia guarded the mountain pass / until the national army arrived / to secure the border.','militia 作单数集合名词，指非正规军队编制的公民武装团体。','当地武装在正规国民军到达前守卫边境。'),M('The newspaper called the full-time national army a militia even though it was a regular professional force.','The newspaper called the locally organised citizen force a militia.','正规职业军队与通常所说的民兵组织不同。','confusable'),[q('Who guarded the pass first?','the local citizen militia','the national army before arriving','the mountain climbers','例句说民兵先守卫山口。'),q('How does the militia differ from the national army here?','it is a locally organised non-regular force','it is a weather station','it is a group of professional doctors','militia 通常是正规军之外的公民武装组织。'),q('Which group best fits militia?','citizens organised for local armed defence','a regular navy on active duty','a civilian hiking club','地方自卫公民武装符合 militia。',1,'context'),q('Militia is used as a?','collective noun for an armed group','verb meaning to guard','plural adjective','militia 在例句中为集合名词。',1,'grammar')]);
P('milk','Milk comes from Old English meolc; it names mammalian liquid, plant-based liquids such as coconut milk, and the verbs for extracting milk or exploiting a resource.',[C('milk.s1','乳类饮品','The farmer chilled the goat milk immediately after the morning milking and delivered it to the creamery.','农场主在早晨挤奶后立即冷藏羊奶，并把它送到乳品厂。','The farmer chilled the goat milk / immediately after the morning milking / and delivered it / to the creamery.','milk 作名词可指哺乳动物分泌的乳汁或作为饮料的奶。','山羊产奶送往乳品厂，符合乳汁义。'),C('milk.s2','植物乳汁','Maya added coconut milk to the curry to soften the chilli and give the sauce a creamy texture.','玛雅在咖喱中加入椰奶，以缓和辣椒味并让酱汁更顺滑。','Maya added coconut milk to the curry / to soften the chilli / and give the sauce a creamy texture.','milk 可构成植物乳状液的名称，如 coconut milk；不代表动物乳汁。','椰奶作为烹调用的乳状液加入咖喱。'),C('milk.s3','挤奶','The farmhand milked the two cows before sunrise so the dairy could collect the fresh supply.','农场工人在日出前给两头奶牛挤奶，以便乳品厂收取新鲜奶源。','The farmhand milked the two cows before sunrise / so the dairy could collect / the fresh supply.','milk 作及物动词，接奶牛或山羊作宾语，表示挤奶。','工人从奶牛身上取奶。'),C('milk.s4','榨取利益','The company was accused of milking the old subscription plan after it stopped offering meaningful updates.','该公司被指在不再提供实质更新后，仍靠旧订阅方案榨取用户的钱。','The company was accused of milking the old subscription plan / after it stopped offering / meaningful updates.','比喻义 milk 表示尽可能从某情境榨取钱财或利益。','继续收费却不更新体现利用旧计划谋利。')],M('The farmhand milked the cows by refusing to collect any milk from them.','The farmhand milked the cows before sunrise and stored the fresh milk.','拒绝取奶与挤奶的动作正相反。'),[q('What happened to the goat milk after milking?','it was chilled and delivered','it was poured into the mountain pass','it was used to paint the barn','例句说羊奶被冷藏并送往乳品厂。',1),q('Why did Maya add coconut milk?','to soften the chilli and make the sauce creamy','to milk a cow','to increase the curry’s sharpness','椰奶令咖喱辣味柔和、质地顺滑。',2),q('In milked the cows, milk is?','a verb meaning to extract their milk','a noun for a plant','an adjective describing the cows','milk 在此是及物动词。',3,'grammar'),q('The firm was accused of milking the plan means it?','extracted money from it unfairly or excessively','stopped charging customers','replaced the plan with free service','比喻义是过度榨取利益。',4,'meaning')]);
P('milk products','Milk products is a transparent noun phrase, milk + products, for foods made from milk; standard alternatives include dairy products and milk products.',C('milk products.s1','食品标签','The allergy guide listed yoghurt, cheese, and butter under milk products so shoppers could check the ingredients.','过敏指南把酸奶、奶酪和黄油列在乳制品项下，方便购物者核对成分。','The allergy guide listed yoghurt, cheese, and butter / under milk products / so shoppers could check the ingredients.','milk products 是复数名词短语，指以奶为原料制成的食品。','指南列举奶酪和酸奶，均属于乳制品。'),M('The label grouped soy sauce and fresh oranges as milk products, although neither contains milk.','The label grouped yoghurt, cheese, and butter as milk products.','酱油和橙子不是以奶制成的产品。'),[q('Which items were listed as milk products?','yoghurt, cheese, and butter','soy sauce and oranges','rice and fresh herbs','指南把酸奶、奶酪和黄油归为乳制品。'),q('Why did shoppers consult the guide?','to check ingredient and allergy information','to measure road distance','to plan a military flight','过敏指南帮助核对食品成分。'),q('Which is a milk product?','cheddar cheese','plain rice','black coffee','奶酪由乳制品制成，属于 milk product。',1,'context'),q('Milk products is grammatically?','a plural noun phrase','a singular verb','an adjective plus preposition','products 是复数名词中心词。',1,'grammar')]);
P('milkweed','Milkweed is named for its milky sap; it refers especially to Asclepias plants, whose pods release silky seeds.',C('milkweed.s1','植物生态','Monarch caterpillars fed on milkweed leaves in the school garden, while seed pods split open in the autumn sun.','学校花园里的帝王蝶幼虫以马利筋叶为食，秋日阳光下种荚裂开。','Monarch caterpillars fed on milkweed leaves / in the school garden / while seed pods split open / in the autumn sun.','milkweed 是马利筋属植物名，常为帝王蝶幼虫提供食物。','幼虫取食叶片、种荚结出丝状种子，符合植物生态。'),M('The guide identified the grass with no milky sap or seed pods as milkweed.','The guide identified the Asclepias with milky sap and silky-seeded pods as milkweed.','无乳状汁液或相关种荚的普通草不符合马利筋特征。'),[q('What fed on the milkweed leaves?','monarch caterpillars','adult frogs','the school gardeners only','帝王蝶幼虫以马利筋叶为食。'),q('What happened to the seed pods?','they split open in autumn','they turned into a road marker','they froze inside a database','秋天种荚裂开并释放种子。'),q('Why is the plant called milkweed?','it has milky sap','it produces dairy cheese','it grows only in milk','名称与植物乳状汁液有关。',1,'word-formation'),q('Which habitat detail fits the example?','a school garden supporting butterfly larvae','a dry runway with no plants','a deep-sea trench','例句中马利筋生长在学校花园并支持幼虫。',1,'context')]);
P('milky','Milky is milk plus adjective-forming -y; it describes a white, cloudy appearance or something mixed with milk.',C('milky.s1','外观描写','A milky haze covered the valley at dawn, blurring the far hills but clearing as the sun rose.','黎明时一层乳白色薄雾笼罩山谷，远山变得模糊，太阳升起后雾气散去。','A milky haze covered the valley at dawn / blurring the far hills / but clearing / as the sun rose.','milky 修饰 haze，表示呈乳白、浑浊的外观。','雾遮蔽远山并随日出消散，呈现乳白色。'),M('The photographer called the transparent, colourless water milky even though it remained perfectly clear.','The photographer called the cloudy white water milky.','完全清澈透明的水没有 milk-like 的乳白浑浊外观。','word-choice'),[q('What looked milky at dawn?','a haze over the valley','the mountain road sign','the sunrise itself','milky 描写山谷薄雾的乳白色外观。'),q('What happened as the sun rose?','the haze cleared','the hills disappeared permanently','the valley flooded','薄雾随日出散去。'),q('Which drink is milky?','tea with plenty of milk','clear water','black coffee without milk','含奶并呈乳白的饮品可称 milky。',1,'context'),q('Milky is formed from milk plus?','-y','-ment','-est','-y 构成表示“像……的”形容词。',1,'word-formation')]);
P('mill','Mill comes through Old English mylen from Latin molina (“mill”); it can be a grain-grinding building or factory, a machine, or the verb to grind.',[C('mill.s1','粮食加工','The old mill turned locally grown wheat into flour using stones powered by the river.','老磨坊用河水驱动石磨，把当地种植的小麦磨成面粉。','The old mill turned locally grown wheat into flour / using stones / powered by the river.','mill 作名词可指磨坊或面粉厂。','石磨把谷物加工成面粉，是磨坊的典型功能。'),C('mill.s2','工业工厂','The textile mill hired two hundred workers to weave cotton into cloth for clothing makers.','纺织厂雇用了两百名工人，把棉花织成供服装制造商使用的布料。','The textile mill hired two hundred workers / to weave cotton into cloth / for clothing makers.','mill 也可泛指制造业工厂，常由行业词修饰，如 textile mill。','工人把棉花织成布，表明这是纺织厂。'),C('mill.s3','磨碎加工','Please mill the roasted peppercorns just before cooking so their aroma stays strong.','请在烹饪前再把烤过的胡椒粒磨碎，这样香气更浓。','Please mill the roasted peppercorns / just before cooking / so their aroma stays strong.','mill 作及物动词，接谷物、香料等，表示磨碎或研磨。','胡椒粒被研磨成粉以释放香气。'),C('mill.s4','人群移动','After the final whistle, excited fans milled around the stadium entrance waiting for the players.','终场哨响后，兴奋的球迷在体育场入口附近徘徊，等待球员。','After the final whistle / excited fans milled around the stadium entrance / waiting for the players.','mill around 作不及物短语，指人群无固定秩序地来回走动。','球迷聚在入口周围等待，符合人群移动义。')],M('The flour mill produced flour by sending whole wheat kernels out without grinding them.','The flour mill ground whole wheat kernels into flour.','不研磨谷粒就不能说磨坊把它们制成面粉。'),[q('What powered the old mill?','the river','a petrol aircraft','the textile workers','水流驱动石磨。',1),q('What did the textile mill produce?','cloth from cotton','flour from peppercorns','milk from wheat','纺织厂把棉花织成布料。',2),q('In mill the peppercorns, mill is?','a verb meaning grind','a noun meaning road distance','an adjective meaning cloudy','mill 在此作动词表示研磨。',3,'grammar'),q('Fans milled around the entrance means they?','moved about in a loose crowd','ground wheat into flour','stood in a strict silent line','mill around 描写人群无序地来回走动。',4,'meaning')]);
P('milled','Milled is the past participle of mill and functions as an adjective for material that has been ground, processed, or shaped by a mill.',C('milled.s1','食品加工','The recipe calls for finely milled cornmeal, which gives the biscuits a smooth crumb instead of a gritty texture.','食谱要求使用细磨玉米粉，这会让饼干口感细腻而非粗糙。','The recipe calls for finely milled cornmeal / which gives the biscuits / a smooth crumb / instead of a gritty texture.','milled 作形容词修饰 cornmeal，描述谷物经过磨粉加工。','细磨粉末制成的饼干不粗糙。'),M('The baker used coarsely cut whole kernels and described them as finely milled cornmeal.','The baker used corn kernels ground into a fine meal.','完整粗粒谷物没有磨成细粉，不能称为 finely milled。','word-choice'),[q('What kind of cornmeal does the recipe require?','finely ground cornmeal','whole unprocessed kernels','large pieces of cheese','milled 表示经过磨制加工。'),q('What texture should the biscuits have?','a smooth crumb','a gritty texture','a rubbery crust','细磨玉米粉使饼干内里细腻。'),q('Which product is milled?','flour ground from wheat','a whole unprocessed ear of corn','a raw milk carton','面粉经过磨坊研磨。',1,'context'),q('Milled is the past participle of?','mill','mile','milk','milled 来自动词 mill。',1,'word-formation')]);
P('millennia','Millennia is the irregular plural of millennium, from Latin mille (“thousand”) plus annus (“year”).',C('millennia.s1','地质时间','The canyon’s layered rock records changes across millennia, far longer than any written human history.','峡谷层叠的岩石记录了数千年间的变化，时间远超有文字记载的人类历史。','The canyon’s layered rock records changes / across millennia / far longer than any written human history.','millennia 是 millennium 的复数，指多个千年时段。','地层形成记录跨越许多个千年。'),M('The geologist used millennia for a single ten-minute interval.','The geologist used a millennium for one thousand years and millennia for many such periods.','millennia 指多个千年，并非十分钟。','measurement'),[q('What period do the canyon layers record?','many thousands of years','one afternoon','a single week','millennia 指多个千年时段。'),q('Millennia is the plural of?','millennium','millimetre','millionaire','millennia 是 millennium 的不规则复数。',1,'plural'),q('Which quantity is measured in millennia?','several thousand-year periods','ten seconds','two kilometres','millennium 的时间长度是一千年。',1,'measurement'),q('Which is correct?','many millennia','many millennium','a millennia','复数形式为 millennia。',1,'plural')]);
})();

(function(){
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('millennium','Millennium comes from Latin mille (“thousand”) plus annus (“year”), by way of Late Latin millennium, for a period of one thousand years.',[C('millennium.s1','历史计时','The observatory marked a millennium of records, spanning one thousand years of measurements from the same valley.','天文台标记了一千年的记录，涵盖同一山谷一千年来的测量数据。','The observatory marked a millennium of records / spanning one thousand years / of measurements from the same valley.','millennium 作名词指一千年；复数为 millennia。','记录跨度正好一千年。'),C('millennium.s2','千禧年之交','Families gathered in the square on New Year’s Eve 1999 to welcome the new millennium.','1999年除夕夜，家人们聚集在广场迎接新的千年纪元。','Families gathered in the square / on New Year’s Eve 1999 / to welcome the new millennium.','the new millennium 常指新的千年时期开始，尤其是千禧年之交。','人们在1999年末庆祝新千年开始。')],M('The historian called the 1,000-year span a century.','The historian called the 1,000-year span a millennium.','century 是一百年，millennium 是一千年。','measurement'),[q('How long did the observatory record span?','one thousand years','one hundred years','one million years','millennium 指一千年。',1,'measurement'),q('When did the families welcome the new millennium?','on New Year’s Eve 1999','at the start of 1900','on the first day of 1990','例句说明他们在1999年末迎接新千年。',2,'context'),q('Millennium is formed from Latin elements meaning?','thousand and year','middle and night','mile and stone','mille 是一千，annus 是年。',1,'word-formation'),q('What is the plural of millennium?','millennia','millenniums only','millenium','常见不规则复数为 millennia。',1,'plural')]);
P('millet','Millet came through Old French millet from Latin milium, a small-seeded grain; it names both the crop and its edible seeds.',[C('millet.s1','旱地作物','The farmer planted millet on the dry hillside because the hardy crop needed less water than rice.','农民在干燥山坡上种植小米，因为这种耐旱作物比水稻需水少。','The farmer planted millet on the dry hillside / because the hardy crop / needed less water than rice.','millet 作名词可指耐旱的小粒谷物作物。','耐旱、适合干地种植体现作物义。'),C('millet.s2','烹饪食材','After rinsing the millet, the cook simmered the grains until they were tender enough for breakfast porridge.','厨师把小米淘洗后慢煮，直到谷粒变软，适合做早餐粥。','After rinsing the millet / the cook simmered the grains / until they were tender enough / for breakfast porridge.','millet 也可指作为食物煮熟食用的小米粒。','淘洗和煮成粥的是谷粒食材。')],M('The cook described millet as a large aquatic rice plant that requires flooded fields.','The farmer described millet as a small-seeded, drought-tolerant grain.','小米为小粒耐旱谷物，不是依赖水淹田的水稻。','confusable'),[q('Why did the farmer choose millet?','it needs less water than rice','it grows only underwater','it produces large fruit','小米耐旱，需水少。',1,'context'),q('What did the cook simmer for porridge?','the millet grains','the hillside soil','rice seedlings still in the field','煮粥的对象是小米粒。',2),q('Which crop best fits a dry hillside?','millet','paddy rice needing flooded fields','water lily','例句指出 millet 适合较干环境。',1,'context'),q('Millet can refer to?','the grain crop or its edible seeds','a unit of length','a kind of dairy product','该词可指作物及其可食谷粒。')]);
P('milligram','Milligram combines milli- (“one thousandth”) with gram; one milligram (mg) is 0.001 gram.',C('milligram.s1','剂量计量','The label states that each tablet contains five milligrams of the active ingredient, so the pharmacist checked the dose carefully.','标签说明每片含五毫克活性成分，因此药剂师仔细核对了剂量。','The label states / each tablet contains five milligrams of the active ingredient / so the pharmacist / checked the dose carefully.','milligram 是质量单位，符号 mg；一毫克等于千分之一克。','标签用毫克表示药物成分质量。'),M('The technician converted 1,000 milligrams into one kilogram.','The technician converted 1,000 milligrams into one gram.','一千毫克等于一克，不是一千克。','measurement'),[q('How much ingredient is in each tablet?','five milligrams','five grams','five kilograms','标签写明每片含五毫克。'),q('One milligram equals?','one thousandth of a gram','one thousand grams','one metre','milli- 表示千分之一。',1,'measurement'),q('Which symbol is commonly used for milligram?','mg','mm','ml','mg 是 milligram 的符号。',1,'measurement'),q('Why did the pharmacist check the label?','to verify the dose amount','to measure the tablet’s length in miles','to count the patient’s appointments','毫克用于核对药物质量剂量。')]);
P('millimeter','Millimeter combines milli- (“one thousandth”) and meter; a millimeter (mm) is one thousandth of a metre.',C('millimeter.s1','长度测量','The engineer measured the gasket at two millimeters thick to ensure it would fit beneath the metal cover.','工程师测得垫圈厚两毫米，以确保它能装进金属盖下面。','The engineer measured the gasket / at two millimeters thick / to ensure it would fit / beneath the metal cover.','millimeter 是长度单位，英式拼写常作 millimetre；一毫米等于千分之一米。','测量垫圈厚度时使用毫米。'),M('The drawing marked the 20-millimeter gap as twenty metres wide.','The drawing marked the gap as 20 millimeters, or 0.02 metre.','20毫米等于0.02米，不是20米。','measurement'),[q('How thick was the gasket?','two millimeters','two centimetres','two metres','工程师测得垫圈厚两毫米。'),q('One millimeter equals?','one thousandth of a metre','one hundred metres','one thousandth of a gram','millimeter 是长度单位，等于千分之一米。',1,'measurement'),q('Which abbreviation is standard for millimeter?','mm','mg','ml','mm 是 millimeter 的常用符号。',1,'measurement'),q('Which item is best measured in millimeters?','the thickness of a thin gasket','the distance between two countries','the volume of a tank','小型垫圈厚度适合用毫米测量。',1,'context')]);
P('million','Million came through Old French million from Italian milione, an augmentative of mille (“thousand”); it means exactly 1,000,000 or an indefinite very large number.',[C('million.s1','精确数值','The census counted one million residents in the district, using the final population register rather than an estimate.','人口普查根据最终人口登记册统计出该地区有一百万人，而非估算值。','The census counted one million residents / in the district / using the final population register / rather than an estimate.','million 作数词表示1,000,000；前有具体数字时通常不加复数-s。','句中是精确的一百万人。'),C('million.s2','泛指很多','After the flood, millions of viewers watched volunteers clear mud from the town’s school and library.','洪灾后，数百万观众观看志愿者清理镇上学校和图书馆的淤泥。','After the flood / millions of viewers watched volunteers / clear mud / from the town’s school and library.','millions of + 复数名词泛指数量极大，未必精确等于数百万。','观众数量是泛指的大量人群。')],M('The report counted exactly five million residents and wrote “five millions residents.”','The report counted exactly five million residents.','具体数词之后 million 通常用单数形式。','grammar'),[q('How many residents were counted in the district?','1,000,000 exactly','about 1,000','several billion','one million 是精确的1,000,000。',1,'measurement'),q('Millions of viewers means?','a very large, unspecified number of viewers','exactly two viewers','one million television sets','millions of 表示数量很多、未必精确。',2),q('Which form is correct after a precise number?','five million residents','five millions residents','five million of resident','数词后用 million 单数并接复数名词。',1,'grammar'),q('What did volunteers clear?','mud from the school and library','a million miles of road','the viewers’ televisions','洪水后志愿者清理学校和图书馆淤泥。',2,'context')]);
P('millionaire','Millionaire came through French millionnaire from million plus the person-forming suffix -aire; it names someone whose wealth reaches at least a million units of currency or assets.',C('millionaire.s1','个人财富','The entrepreneur became a millionaire after selling her software company, though she continued to live in a modest flat.','这位企业家出售软件公司后成为百万富翁，但她仍住在朴素的公寓里。','The entrepreneur became a millionaire / after selling her software company / though she continued to live / in a modest flat.','millionaire 作名词，指资产达到至少一百万货币单位的人；单位需由语境判断。','出售企业带来足以达到百万身家的财富。'),M('The article called a student with no income or assets a millionaire.','The article called an investor with assets worth several million a millionaire.','没有收入或资产的人不符合百万富翁的定义。'),[q('How did the entrepreneur become a millionaire?','she sold her software company','she rented a modest flat','she bought a school lunch','出售公司使她积累了百万级财富。'),q('Does millionaire specify a particular currency?','no; the currency depends on context','yes; it always means US dollars','yes; it only means euros','millionaire 的具体货币单位需由语境确定。'),q('Which person is a millionaire?','someone with assets worth at least a million units','someone who earned one dollar','someone who owns a million books but no wealth','millionaire 指拥有至少百万身家的人。',1,'meaning'),q('Millionaire is formed from million plus?','-aire','-less','-hood','-aire 构成表示人的名词。',1,'word-formation')]);
P('mime','Mime came through French mime from Greek mimos (“imitator”); it can name a wordless performance or the verb to express an action without speech.',C('mime.s1','舞台表演','The mime pretended to push against an invisible wall, making the children laugh without speaking.','哑剧演员假装推一堵看不见的墙，一句话没说就逗笑了孩子们。','The mime pretended to push against an invisible wall / making the children laugh / without speaking.','mime 作名词可指默剧演员或无言表演；作动词指用动作默演。','演员用身体动作表现推墙，没有说话。'),M('The performer mimed the scene by explaining every movement aloud to the audience.','The performer mimed the scene silently through gestures and facial expression.','大声讲解不属于无言默演。','meaning'),[q('What did the mime pretend to push?','an invisible wall','a real bus','a heavy piano','演员默演推一堵看不见的墙。'),q('How did the children respond?','they laughed','they left the theatre','they fell asleep at a desk','表演逗笑了孩子们。'),q('A performer mimes an action by?','using gestures without speaking','reading a script aloud','writing a report','mime 的动词义是无言地用动作表达。',1,'context'),q('Which performance is mime?','a silent scene shown with facial expression','a speech delivered through a microphone','a song with a chorus','默剧靠身体和面部动作表达。',1,'meaning')]);
P('mimetic','Mimetic comes from Greek mimētikos (“imitative”), related to mimēsis (“imitation”); it describes imitation in art, behaviour, or biology.',C('mimetic.s1','生物伪装','The harmless hoverfly has a mimetic pattern that resembles a wasp, discouraging predators from attacking it.','无害的食蚜蝇有类似黄蜂的拟态花纹，使捕食者不敢攻击它。','The harmless hoverfly has a mimetic pattern / that resembles a wasp / discouraging predators / from attacking it.','mimetic 作形容词可指生物的拟态或艺术中的模仿特征。','外形模仿黄蜂起到保护作用。'),M('The hoverfly’s mimetic pattern looked nothing like any other animal and did not imitate anything.','The hoverfly had a mimetic pattern resembling a wasp.','完全没有模仿特征的花纹不应称为 mimetic。'),[q('What does the hoverfly’s pattern resemble?','a wasp','a millimeter ruler','a dairy label','食蚜蝇的花纹模仿黄蜂。'),q('How can the pattern help the hoverfly?','it may discourage predators','it attracts every predator','it produces its food','拟态外形可能降低被捕食风险。'),q('A mimetic artwork would be one that?','imitates the style or form of another work','avoids all resemblance','measures a metre','mimetic 表示模仿性的。',1,'context'),q('Mimetic is related to the idea of?','imitation','measurement','migration only','词源关联模仿、再现。',1,'word-formation')]);
P('mimic','Mimic came through Latin mimicus from Greek mimikos, “of or pertaining to an imitator”; as a verb it means to copy someone’s voice, movement, or behaviour.',C('mimic.s1','声音模仿','The parrot can mimic the microwave’s short beep so accurately that visitors often check the kitchen.','这只鹦鹉能如此逼真地模仿微波炉短促的提示音，以至于访客常去厨房查看。','The parrot can mimic the microwave’s short beep / so accurately / that visitors often check the kitchen.','mimic 作及物动词，后接被模仿的声音、动作或行为。','微波炉提示音是动词 mimic 的宾语。'),M('The parrot mimicked the microwave by producing a completely different sound that nobody could recognise.','The parrot mimicked the microwave’s beep closely enough to fool visitors.','听起来完全不同且无人辨认的声音不能算逼真模仿。'),[q('What sound does the parrot mimic?','the microwave’s short beep','a river running outside','a school bell from another town','鹦鹉模仿微波炉提示音。'),q('What do visitors do because of the mimicry?','they check the kitchen','they leave the house','they turn off the outdoor lights','声音逼真，访客以为微波炉响了。'),q('Which object can be the direct object of mimic?','someone’s accent','to someone’s accent','at an accent','mimic 是及物动词，可直接接模仿对象。',1,'grammar'),q('Which sentence uses mimic correctly?','The child mimicked her teacher’s calm voice.','The child mimicked to her teacher’s voice.','The child was mimic her teacher.','正确结构是 mimic + 直接宾语。',1,'grammar')]);
P('mimicry','Mimicry combines mimic with -ry and names imitation of sounds or behaviour, or a species’ evolved resemblance to another form.',C('mimicry.s1','动物拟态','The harmless hoverfly’s resemblance to a stinging wasp is a form of mimicry that may reduce attacks by birds.','无害的食蚜蝇长得像会蜇人的黄蜂，这种拟态可能减少捕食者的攻击。','The harmless hoverfly’s resemblance to a stinging wasp / is a form of mimicry / that may reduce attacks by birds.','mimicry 作不可数名词，生物学中指一种生物模仿另一种生物的外形或信号。','外形相似可能使捕食者避开食蚜蝇。'),M('The biologist called the hoverfly’s appearance mimicry although it resembled no other animal or signal.','The biologist called the hoverfly’s yellow-and-black resemblance to a wasp mimicry.','完全没有相似特征就没有拟态可言。'),[q('Which two animals are compared?','the hoverfly and a stinging wasp','a hoverfly and a goose','a parrot and a microwave','例句比较食蚜蝇与黄蜂的相似外观。'),q('How might mimicry help the viceroy?','birds may avoid it because it resembles a stinging wasp','it can fly without wings','it becomes poisonous immediately','捕食者可能把它误认为会蜇人的黄蜂。'),q('Which is an example of mimicry?','a harmless insect resembling a stinging wasp','a rock having no resemblance to an animal','a bird migrating south','拟态是形态或信号上的模仿。',1,'context'),q('Mimicry is related to the verb?','mimic','mill','migrate','mimicry 名词由 mimic 派生。',1,'word-formation')]);
P('mince','Mince came through Old French mincier, “to cut into small pieces,” from Latin minutiare, related to minutus (“small”); it is most often used for meat or food.',C('mince.s1','厨房处理','The chef minced the lamb with a sharp knife before mixing it with parsley and spices for the dumpling filling.','厨师先用锋利的刀把羊肉切碎，再将它与欧芹和香料拌成饺子馅。','The chef minced the lamb with a sharp knife / before mixing it / with parsley and spices / for the dumpling filling.','mince 作及物动词，接肉或食物作宾语，表示切成很小的碎块。','羊肉切碎后混入馅料。'),M('The cook minced the lamb by leaving it in one untouched whole joint.','The cook minced the lamb into small pieces before seasoning it.','整块未经切割的肉不是 minced。'),[q('What did the chef mince?','the lamb','the parsley garden','the dumpling plate','羊肉被切成小块。'),q('What happened after mincing?','the lamb was mixed with parsley and spices','the lamb was left whole','the dumplings were frozen on a mountain','切碎后肉与香料混合。'),q('Which kitchen tool could mince meat?','a sharp knife or meat grinder','a measuring tape','a paintbrush','切碎肉可使用刀或绞肉机。',1,'context'),q('Mince means to cut food into?','very small pieces','long unbroken ropes','large flat sheets','mince 的核心是切碎。')]);
P('mincing','Mincing is the -ing form of mince; its adjective sense describes an affectedly delicate or dainty way of walking or speaking.',C('mincing.s1','举止描写','The actor crossed the stage with mincing steps and an exaggeratedly delicate voice to parody the pompous mayor.','演员迈着做作的小碎步、用夸张娇柔的声音穿过舞台，以讽刺傲慢的市长。','The actor crossed the stage with mincing steps / and an exaggeratedly delicate voice / to parody the pompous mayor.','mincing 作形容词修饰 steps 或 speech，描述刻意娇柔、扭捏的举止。','小碎步和刻意娇柔的声音用于讽刺，符合该形容词义。'),M('The dancer’s mincing steps were powerful, broad strides with no trace of affected delicacy.','The performer took mincing steps, moving with an affectedly delicate gait.','大步有力、毫无扭捏感不符合 mincing steps。'),[q('How did the actor cross the stage?','with affectedly delicate steps','with long athletic leaps','without moving at all','mincing steps 是扭捏娇柔的小碎步。'),q('Why did the actor use that voice and gait?','to parody the pompous mayor','to give a weather report','to measure the stage','夸张举止用于讽刺人物。'),q('Which description fits mincing speech?','overly delicate and affected','plain and direct','silent and written','mincing 可形容矫揉造作的说话方式。',1,'context'),q('Here mincing is?','an adjective describing steps','a past-tense verb for cutting meat','a noun for a performance','mincing steps 中 mincing 作形容词。',1,'grammar')]);
P('mind','Mind comes from Old English gemynd (“memory, thought”); it names thought or opinion, and verbs for objecting, paying attention, or taking care of someone.',[C('mind.s1','思维活动','After the alarm sounded, Leo’s mind raced through possible causes before he checked the control panel.','警报响起后，利奥的脑子迅速掠过各种可能原因，然后他去查看控制面板。','After the alarm sounded / Leo’s mind raced through possible causes / before he checked / the control panel.','mind 作名词指思考、记忆和感受的能力或活动。','迅速思考原因体现思维义。'),C('mind.s2','观点意向','I had a mind to take the earlier train, but the railway’s service notice changed my plan.','我原本打算坐早一班火车，但铁路公司的服务通知改变了计划。','I had a mind to take the earlier train / but the railway’s service notice / changed my plan.','have a mind to do something 表示有意或打算做某事。','原本有乘早班车的打算，后因通知改变。'),C('mind.s3','介意反对','Would you mind if we opened the window while the room is being painted?','房间粉刷期间我们打开窗户，你介意吗？','Would you mind / if we opened the window / while the room is being painted?','would you mind if + 过去式是礼貌询问对方是否介意。','说话人征求对方同意。'),C('mind.s4','当心注意','Mind the loose cable near the doorway so nobody trips over it.','当心门口附近松动的电线，免得有人被绊倒。','Mind the loose cable near the doorway / so nobody trips over it.','mind 作祈使动词可表示当心、注意某个危险物。','提醒避开松动电缆以防绊倒。'),C('mind.s5','照看照顾','Could you mind my bicycle for a minute while I buy a ticket at the station kiosk?','我去车站售票亭买票时，你能帮我照看一下自行车吗？','Could you mind my bicycle for a minute / while I buy a ticket / at the station kiosk?','mind 作动词还可表示暂时照看某人或某物。','请求对方在短时间内替自己看管自行车。')],M('Would you mind if I open the window? — No, not at all, means the speaker objects and refuses.','Would you mind if I opened the window? — No, not at all, means the listener does not object.','礼貌问句的否定答复 No, not at all 表示“不介意”。','grammar'),[q('What did Leo’s mind do after the alarm?','it rapidly considered possible causes','it physically checked the control panel','it opened the window','mind 作思维名词。',1),q('I had a mind to take the earlier train means?','I intended or considered doing so','I objected to every train','I watched someone’s bicycle','have a mind to 表示有意或打算。',2,'collocation'),q('Would you mind if we opened the window politely asks whether someone?','objects to the action','will operate the paintbrush','has already left','would you mind 征求是否介意。',3,'grammar'),q('Which pair uses the two verb senses correctly?','Mind the cable means be careful; mind my bicycle means look after it.','Mind the cable means sell it; mind my bicycle means measure its length.','Mind the cable means remember a thought; mind my bicycle means refuse it.','mind 可表示当心，也可表示暂时照看。',4,'context')]);
P('mindset','Mindset is a modern compound of mind and set, naming a relatively established set of attitudes and habits of thought.',C('mindset.s1','学习态度','With a growth mindset, the trainee treated each failed practice run as information about what to improve next.','抱有成长型思维的学员把每次练习失败都当作下一步改进的信息。','With a growth mindset / the trainee treated each failed practice run / as information / about what to improve next.','mindset 作名词指影响思考和应对方式的一套观念或态度。','学员从失败中寻找改进方向体现成长型思维。'),M('The trainee showed a growth mindset by refusing to learn from feedback and assuming every skill was fixed.','The trainee showed a growth mindset by using feedback to improve after a failed practice run.','拒绝学习并认为能力不可改变更接近固定型思维。'),[q('How did the trainee view a failed run?','as useful information for improvement','as proof that practice is pointless','as a reason to stop training forever','成长型思维把失败视为学习信息。'),q('Mindset refers to?','a set of habitual attitudes and ways of thinking','a unit of distance','a physical training room','mindset 指一套思维习惯和态度。'),q('Which action shows a growth mindset?','revising a method after feedback','refusing all feedback','assuming practice can never help','根据反馈调整方法体现成长型思维。',1,'context'),q('Mindset is formed from?','mind + set','mile + stone','milk + weed','该词是 mind 与 set 的复合词。',1,'word-formation')]);
P('mine','Mine has separate histories: possessive mine continues Old English mīn (“my own”), while the excavation noun came through Middle English and Old French; the explosive sense developed later.',[C('mine.s1','物主代词','Those gloves are mine, not yours; I left them beside the greenhouse door yesterday.','那副手套是我的，不是你的；我昨天把它们留在温室门边。','Those gloves are mine / not yours / I left them beside the greenhouse door yesterday.','mine 作独立物主代词，不在后面再接名词。','mine 代替 my gloves，指手套属于说话人。'),C('mine.s2','矿井','The miners descended into the copper mine before dawn and returned to the surface at the end of their shift.','矿工们黎明前下到铜矿井，在班次结束时返回地面。','The miners descended into the copper mine / before dawn / and returned to the surface / at the end of their shift.','mine 作名词可指开采矿物的矿井或矿区。','下井采铜后返回地面符合矿井义。'),C('mine.s3','爆炸装置','The patrol found a buried mine beside the road and closed the area until bomb-disposal experts arrived.','巡逻队在路旁发现一枚埋设地雷，在拆弹专家到达前封锁了该区域。','The patrol found a buried mine beside the road / and closed the area / until bomb-disposal experts arrived.','mine 也可指埋设或水下爆炸装置，语境需区分矿井义。','巡逻队发现爆炸物并请拆弹专家处理。'),C('mine.s4','开采矿物','The company plans to mine lithium from the deposit only after completing an environmental review.','公司计划在完成环境评估后才从矿床开采锂。','The company plans to mine lithium from the deposit / only after completing / an environmental review.','mine 作及物动词，后接矿物或矿藏作宾语，表示开采。','lithium 是被开采的矿物。')],M('The engineer labelled the buried explosive device a copper mine and sent miners underground to dig it out.','The patrol labelled the buried explosive device a land mine and called bomb-disposal experts.','爆炸装置是地雷，不能与开采铜矿的矿井混为一谈。','confusable'),[q('Whose gloves were left by the greenhouse?','the speaker’s','the listener’s','the miners’','mine 作物主代词，表示属于说话人。',1,'grammar'),q('Where did the copper miners work?','underground in a mine','beside a greenhouse','at the road checkpoint','mine 的矿井义是采矿地点。',2),q('Who handled the buried explosive mine?','bomb-disposal experts','the copper miners','the greenhouse owner','爆炸装置需要拆弹专家处理。',3,'context'),q('In mine lithium, mine means?','extract a mineral from the ground','claim the lithium belongs to me','plant lithium underground','及物动词 mine 表示开采矿物。',4,'grammar')]);
P('miner','Miner is mine plus the agent suffix -er, naming someone whose work is extracting coal, ore, or other minerals.',C('miner.s1','采矿工作','The miner checked the ventilation gauge before entering the tunnel because underground air quality can change quickly.','矿工进入隧道前检查了通风仪表，因为地下空气质量可能迅速变化。','The miner checked the ventilation gauge / before entering the tunnel / because underground air quality / can change quickly.','miner 作名词指从事地下或露天矿物开采工作的人。','进入矿道并检查通风是矿工的工作场景。'),M('The miner worked underground extracting ore, but the report said the person had no connection to mining.','The miner worked underground extracting ore from the deposit.','从事矿物开采工作的人就是 miner。'),[q('What did the miner check?','the ventilation gauge','the theatre microphone','the train timetable','矿工入井前检查通风仪表。'),q('Why check underground air?','its quality can change quickly','it measures the road’s mileage','it determines a song’s melody','矿井空气质量可能迅速变化。'),q('Which person is a miner?','a worker who extracts ore from a mine','a visitor who buys mineral water','a guard at a railway station','矿工的工作是开采矿物。',1,'context'),q('The suffix -er in miner indicates?','a person who performs the work','a place where ore is stored','the past tense','-er 常构成人或从事某工作的名词。',1,'word-formation')]);
P('mineral','Mineral came through Old French from Medieval Latin minerale, related to minera (“ore”); it names a naturally occurring substance and can describe something made of minerals.',C('mineral.s1','岩石与营养','The geologist identified quartz as a mineral, while the nutrition label listed calcium as a mineral nutrient.','地质学家把石英鉴定为一种矿物，而营养标签把钙列为矿物质营养素。','The geologist identified quartz as a mineral / while the nutrition label listed calcium / as a mineral nutrient.','mineral 作名词可指天然矿物，也可修饰 nutrient 表示矿物质的。','石英属于地质矿物，钙属于营养语境的矿物质。'),M('The geologist classified manufactured plastic as a naturally occurring mineral crystal.','The geologist classified naturally formed quartz as a mineral.','人工塑料不是天然形成的矿物晶体。'),[q('What did the geologist identify as a mineral?','quartz','plastic','a cheese label','石英是天然矿物。'),q('What was calcium called on the nutrition label?','a mineral nutrient','a road stone','a type of millet','钙是人体需要的矿物质营养素。'),q('Which is a mineral?','naturally formed quartz','a manufactured plastic toy','a paper ticket','天然形成的石英符合矿物定义。',1,'context'),q('In mineral nutrient, mineral functions as?','an adjective modifying nutrient','a past-tense verb','a plural noun only','mineral 在此修饰 nutrient。',1,'grammar')]);
P('mineralization','Mineralization is mineralize plus -ation, naming the process by which minerals are deposited in rock, sediment, or living tissue.',C('mineralization.s1','骨骼化石','The fossil’s mineralization replaced much of its original tissue with minerals while preserving the outline of the ancient leaf.','这块化石的矿化作用以矿物取代了大部分原有组织，同时保留古代叶片的轮廓。','The fossil’s mineralization replaced much of its original tissue / with minerals / while preserving / the outline of the ancient leaf.','mineralization 是名词，指矿物沉积或替代有机物质的过程。','矿物替代组织、保留形态，符合化石矿化。'),M('The report called the leaf mineralization even though no minerals entered or replaced any tissue.','The report described mineralization in which minerals gradually replaced the leaf’s tissue.','没有矿物沉积或替代就没有矿化过程。'),[q('What happened to much of the leaf tissue?','minerals replaced it','it turned into a millimeter','it was carried into a database','矿物取代了部分原有组织。'),q('What did the process preserve?','the outline of the ancient leaf','the living tree’s fruit','a record of migration','化石仍保留古叶片轮廓。'),q('Mineralization is a?','process involving mineral deposition or replacement','type of mineral nutrient','plural form of mineral','-ization 构成表示过程的名词。',1,'word-formation'),q('Which setting can undergo mineralization?','sediment or fossil tissue','a spoken conversation','a train timetable','矿物沉积可发生于沉积物或组织中。',1,'context')]);
P('mineralize','Mineralize combines mineral with -ize, meaning to become mineral-rich or to cause minerals to replace or enter material.',C('mineralize.s1','自然沉积','Over centuries, groundwater can mineralize porous wood, gradually filling its cells with dissolved silica.','数百年间，地下水可能使多孔木材矿化，逐渐把溶解的二氧化硅填入细胞。','Over centuries / groundwater can mineralize porous wood / gradually filling its cells / with dissolved silica.','mineralize 可作及物动词，指使矿物质进入或取代有机物。','溶解的二氧化硅沉积到木材细胞中。'),M('Groundwater mineralized the wood by removing every mineral deposit and leaving the cells empty.','Groundwater mineralized the wood by depositing silica in its pores.','去除矿物而未沉积矿物，与使材料矿化相反。'),[q('What can groundwater do to porous wood?','deposit minerals in its cells','remove all matter from a mountain','turn it into a microphone','mineralize 表示矿物沉积进入材料。'),q('Which mineral was mentioned?','dissolved silica','calcium milk','copper wire','例句指出地下水带有二氧化硅。'),q('Which structure is correct?','mineralize wood with silica','mineralize to wood by silica','mineralize silica at woodly','及物动词 mineralize 可接材料作宾语。',1,'grammar'),q('Mineralize is formed from mineral plus?','-ize','-er','-ous','-ize 可构成表示“使成为/使具有”的动词。',1,'word-formation')]);
P('mingle','Mingle comes from Old English mengan, “to mix”; it means things becoming mixed or a person moving socially among others.',[C('mingle.s1','声音混合','At dusk, the bells from two villages mingled across the valley until the separate melodies became hard to distinguish.','黄昏时，两个村庄的钟声在山谷间交织，渐渐难以分辨各自的旋律。','At dusk / the bells from two villages mingled across the valley / until the separate melodies / became hard to distinguish.','mingle 作不及物动词，常与 with 连用，表示不同声音、气味或事物混合。','两处钟声交融后难以区分。'),C('mingle.s2','社交交谈','At the reception, the new volunteers mingled with local residents instead of staying together by the door.','招待会上，新志愿者们与当地居民交谈，而不是一直聚在门边。','At the reception / the new volunteers mingled with local residents / instead of staying together / by the door.','mingle with people 指在社交场合与不同的人交谈往来。','志愿者主动与居民交流，符合社交义。')],M('At the reception the volunteers mingled with residents by avoiding them and remaining alone all evening.','At the reception the volunteers mingled with residents by introducing themselves and talking with them.','整晚避开他人、独自停留不是社交往来。'),[q('What mingled across the valley?','the bells’ separate melodies','the volunteers’ meal','the roadside traffic','不同村庄的钟声在山谷中交织。',1),q('Whom did the volunteers mingle with?','local residents','only the event organiser','no one; they stayed alone','志愿者与当地居民交谈。',2),q('Which phrase means socialising among guests?','mingle with the guests','mingle under the guests','mingle the guests apart','社交义常用 mingle with someone。',2,'collocation'),q('In the first sentence, mingle means?','to mix so separate sounds blend','to count sounds by distance','to stop the bells','声音混合、难以区分是 mix 的含义。',1,'meaning')]);
})();

(function(){
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('miniature','Miniature came through Italian miniatura, originally painting with minium (“red lead”); it later named a very small detailed painting and then anything made on a reduced scale.',[C('miniature.s1','缩小物件','The museum displayed a miniature railway with tiny stations and working signals arranged across one exhibition table.','博物馆在一张展桌上展出了微型铁路，包括小车站和可运行的信号灯。','The museum displayed a miniature railway / with tiny stations and working signals / arranged across one exhibition table.','miniature 作形容词表示尺寸远小于常规比例，也可作名词指缩小复制品。','铁路被缩小到展桌大小，符合微型义。'),C('miniature.s2','微型复制品','The architect built a miniature of the proposed library so residents could see its shape before construction began.','建筑师制作了拟建图书馆的微型模型，让居民在开工前查看外形。','The architect built a miniature of the proposed library / so residents could see its shape / before construction began.','a miniature of + 对象表示该对象的缩小复制品。','模型让人预览真实建筑的形状。'),C('miniature.s3','细密画','The curator placed the eighteenth-century miniature portrait behind protective glass because the painting was smaller than a postcard.','馆长把这幅十八世纪袖珍肖像画放在保护玻璃后，因为画作比明信片还小。','The curator placed the eighteenth-century miniature portrait / behind protective glass / because the painting was smaller than a postcard.','miniature 作名词还指细密画，尤其是极小的肖像画。','小型肖像画需放在玻璃后保护。')],M('The museum labelled a full-size railway with normal trains a miniature.','The museum labelled its tabletop model railway a miniature.','与真实尺寸相同的铁路不是微型模型。'),[q('What was displayed on one table?','a scaled-down railway','a full-size station','an actual regional rail line','miniature 描述缩小比例的铁路模型。',1),q('What did the architect make for residents?','a small model of the proposed library','the completed library building','a portrait of the curator','miniature of the library 指建筑的缩小模型。',2),q('A miniature portrait is?','a very small detailed painting','a full-size photograph','a sculpture of a railway','miniature 的第三义是袖珍肖像画。',3),q('Which use is adjectival?','a miniature railway','a miniature of the library','the miniatures were displayed','miniature 直接修饰名词 railway。',1,'grammar')]);
P('minibus','Minibus is a modern compound of mini- and bus, named for a bus smaller than a standard full-size vehicle.',C('minibus.s1','团体交通','The hotel sent a minibus to collect the wedding guests, since the narrow lane could not accommodate a coach.','酒店派了一辆小型巴士接婚礼宾客，因为狭窄的小路无法容纳大型客车。','The hotel sent a minibus / to collect the wedding guests / since the narrow lane / could not accommodate a coach.','minibus 作可数名词，指可搭载少量乘客的小型巴士。','狭窄道路适合小巴而非大型客车。'),M('The hotel sent a minibus, a vehicle larger than a full-size coach, down the narrow lane.','The hotel sent a small minibus that could fit down the narrow lane.','minibus 指较小的巴士，不会比大型客车更大。','confusable'),[q('Why did the hotel choose a minibus?','the lane was too narrow for a coach','the guests refused to travel together','the minibus was a railway carriage','小巴尺寸较小，适合狭窄道路。'),q('Who did the vehicle collect?','wedding guests','the road construction crew only','a school of fish','酒店派车接婚礼宾客。'),q('Which vehicle is a minibus?','a small bus for a group of passengers','a private car that must be booked','a full-size intercity coach','minibus 是小型巴士。',1,'confusable'),q('The word minibus combines mini- with?','bus','cab','mile','minibus 是 mini + bus 的复合词。',1,'word-formation')]);
P('minicab','Minicab is a British compound of mini- and cab; it means a private-hire car that must be booked in advance, not necessarily a physically tiny cab.',C('minicab.s1','英国出行','After the concert, we booked a minicab by phone because no licensed street taxi was waiting outside the venue.','音乐会结束后，我们打电话预约了一辆 minicab，因为场馆外没有可直接搭乘的出租车。','After the concert / we booked a minicab by phone / because no licensed street taxi / was waiting outside the venue.','英式英语中 minicab 通常指需提前预约的私人出租车，与可在街边招手搭乘的 taxi 区分。','乘客通过电话预约而非路边拦车。'),M('The visitor flagged down a passing minicab on the street, although that service accepts bookings only in advance.','The visitor booked a minicab by phone before the car arrived.','通常需提前预约的 minicab 不是在街上随手招停的出租车。','confusable'),[q('How did the group get the minicab?','they booked it by phone','they flagged it down at a rank','they boarded it at a bus stop','例句写他们打电话预约。'),q('What does minicab mean in British usage?','a pre-booked private-hire car','a small bus with many seats','any street taxi hailed immediately','minicab 关键是预订的私人出租车服务。',1,'confusable'),q('Must a minicab be physically very small?','no; the name refers to the service, not necessarily its size','yes; it has only one seat','yes; it is always a minibus','名称并不保证车辆尺寸很小。',1,'meaning'),q('Which action fits using a minicab?','arrange the private-hire car before pickup','wave at any taxi on the street','board a city bus without booking','预约后接送符合 minicab 用法。',1,'context')]);
P('minimal','Minimal comes from minimum plus -al and means the smallest possible or only a very small amount or degree.',C('minimal.s1','预算削减','The redesign made minimal changes to the original map, correcting two labels while preserving its layout.','重新设计只对原地图作了极小改动，修正了两个标签，同时保留原有版式。','The redesign made minimal changes to the original map / correcting two labels / while preserving its layout.','minimal 作形容词修饰 changes，表示改动数量或程度很小。','仅修正两个标签且保留版式，说明变动很少。'),M('The designer made minimal changes by replacing every label, colour, and page layout.','The designer made minimal changes by correcting only two labels.','全面更换页面各部分不属于极小改动。'),[q('How many parts of the map were corrected?','two labels','every label and colour','none of the labels or layout','只修改两个标签，改动很少。'),q('Minimal changes means?','very few or very small changes','the greatest possible number of changes','no map was used','minimal 表示数量或程度很小。'),q('Which cost is minimal?','a very small charge','the maximum possible fee','a fee that doubles weekly','minimal 可描述金额很低。',1,'context'),q('Minimal is formed from minimum plus?','-al','-er','-ize','-al 构成形容词 minimal。',1,'word-formation')]);
P('minimalist','Minimalist combines minimal with -ist and names a person or approach that deliberately uses only essential elements.',C('minimalist.s1','艺术设计','The minimalist designer used a single lamp, a wooden chair, and an open floor to keep the studio uncluttered.','这位极简主义设计师只用一盏灯、一把木椅和空旷地面，让工作室保持整洁。','The minimalist designer used a single lamp / a wooden chair / and an open floor / to keep the studio uncluttered.','minimalist 作名词指极简主义者，也可作形容词描述仅保留必要元素的风格。','设计师有意只保留少量家具。'),M('The designer was a minimalist who filled every room with unnecessary ornaments and furniture.','The designer was a minimalist who kept only essential furniture and a few simple objects.','堆满不必要装饰与极简主义理念相反。'),[q('How did the designer furnish the studio?','with only a few essential objects','with ornaments on every surface','with several unused sofas','极简设计仅保留少量必要物件。'),q('A minimalist may be?','a person who favours simplicity','a person who collects every available object','a measurement unit','minimalist 可指奉行简约的人。'),q('Which design is minimalist?','a room with essential furniture and little decoration','a room crowded with ornaments','a room arranged for a military parade','只留必要家具、装饰很少符合极简风格。',1,'context'),q('The suffix -ist often identifies?','a person associated with a practice or belief','a unit of length','a past-tense verb','-ist 常构成人或某种主义的追随者。',1,'word-formation')]);
P('minimally','Minimally is minimal plus -ly and means to the smallest degree or with only a small amount of change.',C('minimally.s1','手术说明','The surgeon made a minimally invasive incision, limiting tissue disruption while still reaching the affected area.','外科医生作了微创切口，在到达患处的同时尽量减少对组织的损伤。','The surgeon made a minimally invasive incision / limiting tissue disruption / while still reaching / the affected area.','minimally 修饰形容词 invasive，表示侵入程度被降到最低。','切口仍可到达患处但尽量减少组织损伤。'),M('The procedure was minimally invasive even though it required several large incisions through healthy tissue.','The procedure was minimally invasive because it required only one small incision.','多处大切口穿过健康组织不符合微创或侵入很少的描述。','word-choice'),[q('What did the surgeon try to limit?','disruption to tissue','the patient’s height','the incision’s colour','微创手术尽量减少组织损伤。'),q('How invasive was the incision?','only to a small degree','as much as possible','not described at all','minimally 表示程度很小。'),q('In minimally invasive, minimally modifies?','the adjective invasive','the noun surgeon','the verb reached','副词 minimally 修饰形容词 invasive。',1,'grammar'),q('Which procedure is minimally invasive?','one using a small incision and little tissue disruption','one using several large cuts','one removing all healthy tissue','较小切口、损伤少符合 minimally invasive。',1,'context')]);
P('minimise','Minimise is the British -ise spelling of minimize, from minimum plus -ise; it means to reduce something or to present it as less important.',[C('minimise.s1','降低风险','The safety team changed the storage layout to minimise the chance of a forklift colliding with pedestrians.','安全团队调整仓储布局，以尽量降低叉车与行人相撞的风险。','The safety team changed the storage layout / to minimise the chance / of a forklift colliding / with pedestrians.','minimise 作及物动词，后接要尽量降低的风险或数量。','调整路线是为了减少碰撞风险。'),C('minimise.s1','淡化问题','The manager tried to minimise the leak by calling it a minor drip, although water had damaged three boxes.','经理试图把漏水说得无关紧要，称其为小滴漏，尽管已有三箱货物被水损坏。','The manager tried to minimise the leak / by calling it a minor drip / although water had damaged three boxes.','minimise 也可表示轻描淡写、淡化问题的重要性。','损坏已有三箱，却把漏水说成小问题。')],M('The safety redesign minimised collision risk by adding blind corners and removing warning lights.','The safety redesign minimised collision risk by separating forklift lanes from pedestrian paths.','增加盲区和撤除警示不会降低碰撞风险。'),[q('Why did the team change the layout?','to reduce the risk of a collision','to increase forklift speed','to make pedestrians use the same lane','minimise 的第一义是尽量减少风险。',1,'context'),q('How did the manager minimise the leak?','by describing it as a minor drip','by repairing the damaged boxes','by reporting the full extent immediately','他试图淡化问题严重性。',1,'context'),q('Which option gives the usual British -ise spelling and US -ize spelling, respectively?','minimise; minimize','minimize; minimise','minimice; minimizee','-ise is common in British English and -ize in US English; British style preferences can vary.',1,'spelling'),q('What can minimise mean besides reduce?','to make a problem seem less important','to prove the problem is impossible','to make an object larger','minimise 也可指淡化、轻描淡写。',1,'meaning')]);
P('minimize','Minimize is minimum plus -ize and means to reduce an amount as far as possible or to treat a concern as less important.',[C('minimize.s1','节能措施','The new insulation should minimize heat loss through the roof during the coldest months.','新保温层应能在最冷的月份尽量减少屋顶散热。','The new insulation should minimize heat loss / through the roof / during the coldest months.','minimize 作及物动词，后接要尽量减少的量或风险。','保温材料的作用是减少热量流失。'),C('minimize.s2','轻视担忧','The spokesperson did not minimize residents’ concerns; she published the test results and answered their questions.','发言人没有轻视居民的担忧，而是公布检测结果并回答问题。','The spokesperson did not minimize residents’ concerns / she published the test results / and answered their questions.','minimize 也可表示把问题说得不重要；否定形式表示没有淡化。','公布数据并答疑表明没有轻视居民担忧。')],M('The spokesperson minimized residents’ concerns by publishing the full test results and arranging an independent review.','The spokesperson addressed residents’ concerns by publishing results without minimizing their importance.','公开结果并安排独立审查是在认真回应，不是淡化担忧。','meaning'),[q('What should the insulation minimize?','heat loss through the roof','the roof’s height','the number of winter days','保温层旨在减少屋顶散热。',1,'context'),q('What did the spokesperson do about residents’ concerns?','she addressed them with results and answers','she called them unimportant','she refused to publish the tests','发言人没有淡化担忧，而是提供信息回应。',2),q('Which spelling is standard in US English?','minimize','minimisee','minimice','US English commonly uses the -ize spelling.',1,'spelling'),q('Minimize can mean?','reduce as much as possible or downplay','increase to the maximum','measure in milligrams','该词有减少和淡化两种用法。')]);
P('minimum','Minimum comes from Latin minimum, the neuter form of minimus (“smallest”); it names the least amount or describes the lowest permitted level.',[C('minimum.s1','最低人数','The workshop requires a minimum of six participants, so the organiser postponed it when only four registered.','研讨会至少需要六名参加者，因此只有四人报名时，组织者推迟了活动。','The workshop requires a minimum of six participants / so the organiser postponed it / when only four registered.','a minimum of + 数量表示最低限度或最少数量。','四人未达到至少六人的要求。'),C('minimum.s2','最低安全标准','The contractor kept the heating at the minimum safe temperature while the empty building was repaired.','维修空置建筑期间，承包商把暖气维持在最低安全温度。','The contractor kept the heating / at the minimum safe temperature / while the empty building / was repaired.','minimum 作形容词修饰 temperature，表示最低但仍符合要求的。','最低温度仍需满足安全标准。')],M('The organiser proceeded with four participants even though the stated minimum was six.','The organiser postponed the session because four participants were below the minimum of six.','四人少于规定的六人最低数，应未达到门槛。','measurement'),[q('How many people were required at minimum?','six','four','ten thousand','活动最低人数是六人。',1,'measurement'),q('Why was the workshop postponed?','only four people had registered','the minimum had been exceeded','the building was already repaired','四人少于最低报名人数。'),q('In minimum safe temperature, minimum is?','an adjective describing the lowest acceptable level','a verb meaning heat','a noun for the participants','minimum 在此修饰 temperature。',2,'grammar'),q('Which phrase is correct?','a minimum of six participants','a minimum to six participants','minimum six participant are required','常用结构是 a minimum of + 数量。',1,'collocation')]);
P('mining','Mining is mine plus -ing and names the industry or process of extracting coal, metals, stone, or other minerals from the ground.',C('mining.s1','矿业管理','The region’s mining industry funded a water study after residents reported sediment in the stream below the ore site.','居民报告矿区下游溪流出现沉积物后，该地区矿业出资开展水质研究。','The region’s mining industry funded a water study / after residents reported sediment / in the stream / below the ore site.','mining 作名词指开采矿物的行业或过程。','矿区活动与下游溪流的沉积物有关。'),M('The mining company extracted no minerals and conducted only a study of bird migration.','The mining company extracted ore from the ground and monitored its effects on nearby water.','未从地下开采矿物的公司没有从事 mining。'),[q('What did residents find in the stream?','sediment below the ore site','a new bus schedule','milk products','居民在矿区下游溪流发现沉积物。'),q('What did the mining industry fund?','a study of the water','a concert in the capital','a new railway map','矿业出资调查水质问题。'),q('Mining is the process of?','extracting minerals from the ground','measuring the length of a tunnel only','producing milk','mining 指从地下开采煤、金属或其他矿物。'),q('Which place is a mining site?','an open pit where copper ore is extracted','a dairy that packages yoghurt','a garden with milkweed','露天铜矿坑是采矿地点。',1,'context')]);
P('minister','Minister comes from Latin minister, “servant or attendant”; it names a government official or a Protestant clergy member, and can be a verb meaning to care for someone.',[C('minister.s1','政府官员','The transport minister announced new safety inspections after engineers found cracks in two railway bridges.','工程师在两座铁路桥上发现裂缝后，交通部长宣布了新的安全检查。','The transport minister announced new safety inspections / after engineers found cracks / in two railway bridges.','minister 作名词可指负责政府部门的高级官员。','交通部长发布本部门安全政策。'),C('minister.s2','宗教牧职','The village minister visited the hospital each Thursday to pray with patients who requested spiritual support.','村里的新教牧师每周四探望医院里需要精神支持的患者，并与他们祈祷。','The village minister visited the hospital each Thursday / to pray with patients / who requested spiritual support.','minister 在部分新教教会中指牧师或教会领袖。','探望患者并提供祈祷支持是宗教牧职。'),C('minister.s3','照料援助','Volunteers ministered to evacuees at the school, providing blankets and helping families contact relatives.','志愿者在学校照料撤离居民，提供毯子并帮助家庭联系亲人。','Volunteers ministered to evacuees at the school / providing blankets / and helping families / contact relatives.','minister to someone 作动词短语，表示照料、服侍或满足其需要。','志愿者为撤离者提供物资和帮助。')],M('The transport minister was described as a church clergyman even though the person managed national rail policy.','The transport minister was a government official responsible for rail policy.','管理国家交通政策的是政府部长，不是教会牧师。','confusable'),[q('What did the transport minister announce?','new railway safety inspections','a hospital prayer service','a new mineral deposit','部长宣布检查铁路桥梁。',1),q('What did the village minister offer patients?','spiritual support and prayer','railway inspections','a new mining permit','该义项指新教牧师提供宗教支持。',2),q('In ministered to evacuees, the verb means?','cared for and served their needs','appointed them to parliament','measured their luggage','minister to 表示照料、援助。',3,'collocation'),q('Which person is a government minister?','an official leading a transport department','a volunteer serving food at one event','a miner in a copper pit','部长负责政府部门事务。',1,'meaning')]);
P('ministry','Ministry came through Old French from Latin ministerium (“service, office”); it names a government department or its ministerial administration.',C('ministry.s1','政府部门','The Ministry of Transport published the bridge inspection schedule and asked local councils to report any urgent defects.','交通部公布了桥梁检查日程，并要求地方议会报告紧急缺陷。','The Ministry of Transport published the bridge inspection schedule / and asked local councils / to report any urgent defects.','Ministry of + 部门名称指政府部委，通常专名首字母大写。','交通部发布该领域的全国检查安排。'),M('The Ministry of Transport published national bridge rules, but the report said it was a private fishing club.','The Ministry of Transport published the national bridge rules as a government department.','负责全国交通政策的 Ministry 是政府部门，不是私人俱乐部。'),[q('Which ministry issued the schedule?','the Ministry of Transport','the village church','the local fishing club','例句中的部门是交通部。'),q('What did local councils have to report?','urgent bridge defects','the number of migratory birds','the price of milk','地方议会需报告紧急桥梁缺陷。'),q('A ministry is generally?','a government department and its administration','a single private taxi','a mineral extraction machine','ministry 可指政府部委。'),q('Why is Ministry capitalized in the example?','it is part of the department’s formal name','all nouns are capitalized in English','it starts a question','正式部门名称中 Ministry 首字母大写。',1,'capitalization')]);
P('minor','Minor comes from Latin minor, “smaller or less”; it describes something less serious, a person below adulthood, a secondary college subject, or a musical mode.',[C('minor.s1','轻微问题','The report found a minor crack in the plaster but no structural damage to the building.','报告发现灰泥上有一条轻微裂缝，但建筑结构没有受损。','The report found a minor crack in the plaster / but no structural damage / to the building.','minor 作形容词表示程度、重要性或规模较小。','灰泥裂缝轻微，建筑结构没有损坏。'),C('minor.s2','法律年龄','The venue requires a parent or guardian to accompany any minor after 9 p.m.','场馆规定，晚上九点后任何未成年人都必须由家长或监护人陪同。','The venue requires a parent or guardian / to accompany any minor / after 9 p.m.','minor 作名词指未达到法律成年年龄的人。','需要监护人陪同是对未成年人的规定。'),C('minor.s3','大学辅修','At university, Dev chose biology as his minor while keeping history as his main subject.','在大学里，德夫把生物学选为辅修，同时以历史为主修。','At university / Dev chose biology as his minor / while keeping history / as his main subject.','minor 作名词指大学里的辅修科目，通常次于主修。','生物为辅修、历史为主修。'),C('minor.s4','辅修行为','She decided to minor in economics so she could add business courses to her engineering degree.','她决定辅修经济学，以便在工程学位中增加商科课程。','She decided to minor in economics / so she could add business courses / to her engineering degree.','minor 作动词时常用 minor in + 学科，表示辅修该科目。','经济学是加入工程学位的第二学科。'),C('minor.s5','音乐调式','The quartet shifted into a minor key, giving the final passage a darker and more reflective sound.','四重奏转入小调，使最后乐段听起来更阴郁、更沉思。','The quartet shifted into a minor key / giving the final passage / a darker and more reflective sound.','minor 作音乐形容词，指小调或小音阶的。','小调音色使乐段显得深沉。')],M('The quartet shifted into a minor key to create a bright major-key sound.','The quartet shifted into a minor key to create a darker, more reflective sound.','小调与明亮的大调效果相反。','confusable'),[q('How serious was the crack?','it was minor and caused no structural damage','it destroyed the whole building','it was in a musical key','minor 作形容词表示轻微。',1),q('Who must be accompanied after 9 p.m.?','a person below the legal age of adulthood','a government minister','a professor with a minor degree','名词 minor 指未成年人。',2),q('What did Dev study as his secondary subject?','biology as his minor','history as his minor and main subject','economics as his engineering degree','minor 名词指大学辅修科目。',3),q('Which statement uses minor as a verb?','She plans to minor in economics.','She has a minor crack.','The venue admits no minors.','minor in + 学科是动词用法。',4,'grammar')]);
P('minority','Minority is minor plus -ity, from Latin minoritas; it means the smaller number or a group smaller than the larger group.',C('minority.s1','人数比较','Only a minority of the council voted against the plan; most members supported the new bus route.','只有少数议员投票反对该计划；大多数成员支持新的公交线路。','Only a minority of the council voted against the plan / most members supported / the new bus route.','a minority of + 复数名词表示少数成员；可根据语境接单数或复数动词。','反对票少于支持票，体现少数义。'),M('The article called the group a minority even though it contained ninety people out of a council of one hundred.','The article called the group a majority because ninety of one hundred members supported it.','九十人占一百人的大多数，不是少数。','confusable'),[q('How many council members opposed the plan?','only a smaller group','almost all members','no council members existed','minority 指人数较少的一方。'),q('What did most council members support?','the new bus route','the opposition vote','closing the council','例句说多数议员支持新线路。'),q('A minority group is?','a group smaller than the larger population group','the largest group in every case','one individual only','minority 指相对较小的群体。',1,'meaning'),q('Minority is formed from minor plus?','-ity','-ist','-ment','-ity 构成抽象名词 minority。',1,'word-formation')]);
P('minstrel','Minstrel came from Old French menestrel via Medieval Latin ministralis (“servant, entertainer”); in historical English it names a travelling singer or musician.',C('minstrel.s1','中世纪音乐','The minstrel travelled between market towns, singing ballads and reciting poems for audiences in the inn yard.','吟游诗人在集市城镇间旅行，在客栈院子里为听众演唱民谣、朗诵诗歌。','The minstrel travelled between market towns / singing ballads / and reciting poems / for audiences in the inn yard.','minstrel 作名词指历史上的巡回艺人，常以歌唱或吟诗谋生。','跨城演唱民谣、朗诵诗歌符合历史义。'),M('The medieval minstrel sat silently in the inn and refused to sing or tell stories to anyone.','The medieval minstrel entertained inn audiences by singing and reciting verse.','拒绝表演的沉默旅客不符合吟游艺人的含义。'),[q('What did the minstrel perform?','ballads and poems','railway inspections','laboratory measurements','吟游艺人唱民谣、朗诵诗歌。'),q('Where did the minstrel travel?','between market towns','only between hospital wards','from one planet to another','例句写艺人在集市城镇之间巡回。'),q('A historical minstrel was a travelling?','entertainer and musician','government minister','miner','minstrel 指巡回表演的艺人。'),q('Which role fits the medieval word?','singing for an audience in an inn yard','repairing a railway bridge','booking a private taxi','巡回歌者在客栈为听众表演。',1,'context')]);
P('mint','Mint has separate histories: the herb continues Latin mentha; the coin-making place comes from Latin moneta through Old English mynet; the perfect-condition sense is like a freshly made coin.',[C('mint.s1','草本调味','The cook crushed fresh mint leaves into the yoghurt sauce to give it a cool aroma beside the grilled lamb.','厨师把新鲜薄荷叶捣碎拌进酸奶酱，为烤羊肉配上清凉香气。','The cook crushed fresh mint leaves / into the yoghurt sauce / to give it a cool aroma / beside the grilled lamb.','mint 作名词指薄荷植物，也可指薄荷糖。','新鲜叶片作为调味草本使用。'),C('mint.s2','货币制造','The national mint struck a commemorative coin to mark the opening of the new railway line.','国家造币厂铸造了一枚纪念币，以纪念新铁路线路开通。','The national mint struck a commemorative coin / to mark the opening / of the new railway line.','mint 作名词指制造硬币的官方机构或场所。','该机构铸造纪念币。'),C('mint.s3','巨额财富','The athlete made a mint from endorsement deals after winning the championship.','这位运动员夺冠后靠代言合同赚了大笔钱。','The athlete made a mint from endorsement deals / after winning the championship.','make a mint 是非正式表达，表示赚得巨款。','代言带来大量收入。'),C('mint.s4','崭新状态','The collector kept the vintage train ticket in mint condition inside a protective sleeve.','收藏家把那张老式火车票放在保护套里，保持完好如新。','The collector kept the vintage train ticket / in mint condition / inside a protective sleeve.','mint condition 表示完好如新、几乎未使用。','保护套帮助票券保持 pristine 状态。'),C('mint.s5','铸币创造','The Treasury will mint a special coin with a design chosen by schoolchildren.','财政部将铸造一枚特别硬币，图案由学童选定。','The Treasury will mint a special coin / with a design / chosen by schoolchildren.','mint 作及物动词表示铸造硬币，也可引申为创造新词。','财政部制作新硬币。')],M('The collector called a torn, heavily stained ticket mint condition.','The collector called the uncreased ticket mint condition because it looked unused.','严重破损和污渍与完好如新相矛盾。'),[q('What flavour did the leaves add to the sauce?','a cool mint aroma','a metallic coin taste','a hot pepper smell','薄荷叶带来清凉香气。',1),q('What did the national mint make?','a commemorative coin','a railway station','a yoghurt sauce','造币厂铸造纪念币。',2),q('To make a mint means to?','earn a very large amount of money','open an herb garden','destroy a coin','make a mint 表示赚得巨款。',3,'collocation'),q('Which sentence uses mint as a verb?','The Treasury will mint a new coin.','The sauce contains mint.','The ticket is in mint condition.','mint 作动词表示铸造。',5,'grammar')]);
P('minus','Minus comes from Latin minus (“less”), the neuter form of minor; it marks subtraction, a value below zero, or a disadvantage.',[C('minus.s1','算术运算','The worksheet asks students to calculate twelve minus five before checking the answer against the number line.','练习要求学生先计算十二减五，再用数轴核对答案。','The worksheet asks students to calculate twelve minus five / before checking the answer / against the number line.','minus 作介词或符号表示从前一数中减去后一数。','算式 12 − 5 是减法。'),C('minus.s2','零下温度','The forecast predicts minus eight degrees overnight, so the pipes in the empty cabin need insulation.','天气预报说夜间将达到零下八度，因此空置小屋里的管道需要保温。','The forecast predicts minus eight degrees overnight / so the pipes / in the empty cabin / need insulation.','minus 作形容词标在数字前，表示低于零。','零下温度可能冻坏管道。'),C('minus.s3','缺点因素','The only minus of the apartment is its long walk from the nearest underground station.','这套公寓唯一的缺点是离最近的地铁站要走很远。','The only minus of the apartment / is its long walk / from the nearest underground station.','minus 作名词指不利之处或缺点，常与 plus 对照。','交通距离是公寓的不利因素。')],M('Twelve minus five equals seventeen.','Twelve minus five equals seven.','减法结果是七，不是十七。','measurement'),[q('What is twelve minus five?','seven','seventeen','sixty','12 − 5 = 7。',1,'measurement'),q('What does minus eight degrees mean?','eight degrees below zero','eight degrees above zero','eight degrees of distance','minus 表示温度低于零。',2,'measurement'),q('What is the apartment’s minus?','the long walk to the underground','its low heating bill','its nearby station','minus 作名词指缺点。',3),q('Which word contrasts with a minus point?','plus','mild','migrate','plus 可与 minus 对照表示优点。',3,'confusable')]);
P('minuscule','Minuscule comes from French minuscule and Latin minuscula (“rather small”); it first named a small written letter and later anything extremely small.',[C('minuscule.s1','数量极少','Only a minuscule amount of ink remained in the cartridge, so the printer stopped halfway through the diagram.','墨盒里只剩极少量墨水，因此打印机在图表打印到一半时停了下来。','Only a minuscule amount of ink remained / in the cartridge / so the printer stopped / halfway through the diagram.','minuscule 作形容词表示尺寸或数量极小。','墨水所剩无几，无法完成打印。'),C('minuscule.s2','小写字母','The calligrapher practised a minuscule b beside a capital B to compare the lowercase and uppercase forms.','书法家在大写 B 旁练习小写字母 b，以比较大小写形式。','The calligrapher practised a minuscule b / beside a capital B / to compare the lowercase and uppercase forms.','minuscule 作名词可指小写字母，与大写字母相对。','b 和 B 对比小写与大写字形。')],M('The printer stopped because a minuscule amount of ink meant the cartridge was completely full.','The printer stopped because only a minuscule amount of ink remained.','minuscule 表示很少，不是装得很满。','meaning'),[q('Why did the printer stop?','only a tiny amount of ink remained','the cartridge was full','the diagram had no labels','minuscule amount 表示所剩极少。',1),q('Which letter did the calligrapher practise?','a lowercase b','a capital B only','a number eight','例句指出练习的是小写字母 b。',2),q('Minuscule first named what?','a small written letter','a large capital letter','a unit of time','该词最初指小写字母。',2,'word-formation'),q('Which amount is minuscule?','a trace of ink','a full litre','a large lake','minuscule 表示极小的量。',1,'context')]);
P('minute','Minute has two pronunciations and histories: the time unit and meeting note came from Latin minuta (“small part”); adjective minute comes from minutus (“small”).',[C('minute.s1','时间单位','The courier arrived in four minutes, just before the archive office closed for the day.','快递员四分钟后抵达，恰好赶在档案室当天关门前。','The courier arrived in four minutes / just before the archive office / closed for the day.','minute 作名词 /ˈmɪnɪt/ 指六十秒。','四分钟是具体的时间长度。'),C('minute.s2','短暂片刻','Wait a minute while I retrieve the signed form from the locked cabinet.','稍等片刻，我去锁着的柜子里取签过字的表格。','Wait a minute / while I retrieve the signed form / from the locked cabinet.','a minute 也可非正式表示一小会儿，不一定严格六十秒。','说话人请对方短暂等候。'),C('minute.s3','会议记录','The secretary circulated the minutes of the council meeting so members could correct the record before approval.','秘书分发了议会会议记录，让成员在批准前核对内容。','The secretary circulated the minutes of the council meeting / so members could correct the record / before approval.','minutes /ˈmɪnɪts/ 常用复数，指正式会议记录。','成员核对的是会议发言和决议记录。'),C('minute.s4','极小精细','The conservator made minute adjustments to the frame, moving each screw only a fraction of a turn.','修复师对画框作了极细微的调整，每颗螺丝只转动一小部分。','The conservator made minute adjustments to the frame / moving each screw / only a fraction of a turn.','形容词 minute /maɪˈnjuːt/ 意为极小或极其细致，重音与时间名词不同。','螺丝只微微转动，说明调整很细小。')],M('The secretary circulated the meeting minute, meaning one sixtieth of an hour, for members to approve.','The secretary circulated the meeting minutes, the written record of what was said and decided.','会议记录通常用复数 minutes；minute 单数的常见义是六十秒。','confusable'),[q('How long did the courier take?','four periods of sixty seconds','four hours','four miles','minute 作时间单位时一分为六十秒。',1,'measurement'),q('Wait a minute asks someone to wait?','for a short time','for exactly one year','until the meeting is cancelled','此处 a minute 是短暂一会儿。',2),q('What did the secretary circulate?','the written record of the meeting','a clock showing four minutes','the frame’s tiny screws','meeting minutes 是会议记录。',3,'context'),q('How is adjective minute meaning tiny pronounced?','/maɪˈnjuːt/','/ˈmɪnɪt/ like the time unit','/ˈmaɪnət/','表示极小的形容词重音在第二音节，和时间名词不同。',4,'confusable')]);
P('minutely','Minutely is the adjective minute (“very small, exact”) plus -ly; it means in great detail, with attention to tiny points.',C('minutely.s1','仔细检查','The inspector examined each hinge minutely, recording even the smallest sign of rust in the maintenance log.','检查员细致地检查每个铰链，连最小的锈迹也记录在维护日志中。','The inspector examined each hinge minutely / recording even the smallest sign of rust / in the maintenance log.','minutely 修饰 examined，表示检查得非常仔细；此处读音源自 minute“细微的”。','检查员关注细节并记录微小锈迹。'),M('The inspector examined the hinges minutely by glancing at them once from across the room.','The inspector examined each hinge minutely, checking its surface for small defects.','远远扫视一眼不是详尽细致的检查。','word-choice'),[q('How did the inspector examine each hinge?','in great detail','from far away without looking closely','only once every minute','minutely 表示仔细详尽地。'),q('What tiny defect did the inspector record?','a small sign of rust','a broken railway bridge','a large crack in the wall','日志记录了最小的锈迹。'),q('Which action is done minutely?','checking each screw and surface for tiny flaws','glancing at a machine from the doorway','reading only the title','逐处查找微小缺陷属于 minutely。',1,'context'),q('Minutely here comes from which meaning of minute?','very small or precise','a unit of sixty seconds only','a written meeting record','minutely 源自表示细微、精确的形容词 minute。',1,'confusable')]);
})();


})();
